/* -------- toast -------- */
let tT;
/* toast 只放一句话（2026-10-26 口径：产品文案不超过 11 字）；需要用户读完的结果说明走 tAlert。超长时控制台告警（演示提示除外） */
function toast(m){
  const t=document.getElementById('toast');
  if(String(m).replace(/\s/g,'').length>11&&!/演示|模拟/.test(String(m)))console.warn('toast 文案超过 11 字：'+m);
  t.textContent=m;t.classList.remove('demo','lo');t.onclick=null;t.classList.add('show');
  /* 停留时长随文案长度自适应：短提示仍约 3 秒，长文案最多延到 6 秒，避免没读完就消失 */
  clearTimeout(tT);tT=setTimeout(()=>t.classList.remove('show'),Math.min(6000,2200+String(m).length*90));
}
/* 演示提示（2026-10-26）：原型用它替代真实能力（扫码、拨号、播放视频、微信系统页）或说明演示开关的切换结果。
   不是产品 toast：带「演示」角标与琥珀描边、左对齐可多行、停留稍长，不受 11 字限制；真实产品不会出现这类提示 */
function demoToast(m){
  const t=document.getElementById('toast');m=String(m);
  const body=m.replace(/^演示(简化)?[:：]\s*/,'');
  t.innerHTML='<i class="demo-tag">演示</i>'+body+'<i class="demo-x" aria-hidden="true">×</i>';
  t.classList.toggle('lo',body.length>22);/* 超过一行的演示提示贴在底栏上方，不遮住它在说明的内容（2026-10-27） */
  t.classList.add('show','demo');
  t.onclick=function(){clearTimeout(tT);t.classList.remove('show')};/* 整块可点关闭（2026-10-27） */
  clearTimeout(tT);tT=setTimeout(()=>t.classList.remove('show'),Math.min(8000,3000+m.length*80));
}
/* 处理完成的统一落点：回到传入的来源页（请假审批、销假确认传 lvdFrom），未传时回首页 */
function done(m,to){go(to||'sc-home');toast(m)}
const lvEsc=t=>t.replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
/* 请假单证明材料大图：复用通行抓拍的全屏预览遮罩（点任意处关闭），同一单多图时左右箭头循环切换、标题带页码，单图不显示箭头（与家长端 lvShotOpen 同构） */
let lvShotArr=[],lvShotIdx=0,lvShotCap='';
function lvShot(el){
  const imgs=[...el.parentNode.querySelectorAll('img')];
  lvShotArr=imgs.map(i=>i.getAttribute('src'));lvShotIdx=Math.max(0,imgs.indexOf(el));
  const sc=el.closest('.screen'),stu=sc.querySelector('.kv .v').textContent.split(' · ')[0],ty=sc.querySelector('.card b').firstChild.textContent;
  lvShotCap=stu+' · '+ty+'证明材料';
  lvShotShow();document.getElementById('shot-view').classList.add('show');
}
function lvShotShow(){
  const n=lvShotArr.length;
  document.querySelector('#shot-view img').src=lvShotArr[lvShotIdx];
  document.getElementById('shot-cap').textContent=lvShotCap+(n>1?' '+(lvShotIdx+1)+'/'+n:'');
  document.getElementById('shot-prev').style.display=n>1?'flex':'none';
  document.getElementById('shot-next').style.display=n>1?'flex':'none';
}
function lvShotNav(d,ev){ev.stopPropagation();const n=lvShotArr.length;lvShotIdx=(lvShotIdx+d+n)%n;lvShotShow()}
/* -------- 智慧放学（播报控制台）：任教班级默认为与全校班级同一布局的年级卡三列格子（tdStyle='grid'，与线上小程序一致），放学 / 延迟操作经点击班级格子拉起的「放学确认」半屏完成（参考 tn 原型）；
   另有两种对比预览样式（tdStyle）：row 每班一行的紧凑列表（主行段 + 其余段摘要）、card 原「班级卡 × 班次段」（与家长端同构）；出校计数与应到人数不上屏（阈值自动播报仍在后台生效） --------
   班次（段数 / 起止时间 / 别名）由学校端「学生班次」按班级配置；本页五个班同为 3年级、一天打卡 4 次两段（上午 / 下午），
   五个班分别预置 未放学 / 放学中 / 延迟放学 / 已放学 / 今天没有课 示例；
   主行=当前最相关段（第一个未播报 / 延迟的段，全部已播报取最后一段），其余段压缩为一行灰字摘要（未播报段印计划放学时间）；
   状态四态：wait 未放学（灰，计数中）/ done 已放学（青碧）/ delay 延迟放学（朱红，仅预计时间上屏）/ closed 未放学 · 已结束（灰，系统收口、无播报时间）；
   另有展示态 going 放学中（琥珀，与家长端一致）：done 段自放学时刻起 10 分钟内按「放学中」显示（TD_GOING_SEC），到时自动转「已放学」，由头部时钟每秒检查并刷新；
   触发双通道：半屏「开始放学」（tdOpen → tdBroadcast）与出校计数达阈值自动播报（tdAutoHit），已手动放学的班达标不重播；
   演示编排与家长端对齐：3年级-2班 下午段 16:44 由王老师手动播报（家长端消息「王老师发起放学」16:44）、上午段 11:48 自动播报；
   演示基准时点 16:44:05（家长端为 17:05:47，本页停在播报动作发生前的时刻）；
   live 覆盖层（TD_LIVE）承载演示内的实际操作，各预览（上午时点 / 收口 / 第三段 / 无班次）为渲染时叠加的形态开关，重置一并清空 */
const TD_ST={wait:['未放学','wait'],going:['放学中','going'],done:['已放学','done'],delay:['延迟放学','delay'],closed:['未放学 · 已结束','wait']};
const TD_GOING_SEC=600;
 /* 开始放学后 10 分钟内为「放学中」（与家长端 ing 态同口径、同琥珀配色） */
/* 展示态：done 段放学时刻（HH:MM）距当前时钟不足 10 分钟 → going */
function tdView(s){if(s.st!=='done'||!s.t)return s.st;const [h,m]=s.t.split(':').map(Number),d=tdSec()-(h*3600+m*60);return d>=0&&d<TD_GOING_SEC?'going':'done'}
const TD_CLS=[
 {k:'c32',nm:'3年级-2班',role:'班主任',rc:'navy',total:45,segs:[
   {al:'上午',st:'done',t:'11:48',pt:'11:30',n:42,by:'auto'},
   {al:'下午',st:'wait',t:'',pt:'16:30',n:0,by:''}]},
 {k:'c31',nm:'3年级-1班',role:'任课老师',rc:'gray',total:44,segs:[
   {al:'上午',st:'done',t:'11:50',pt:'11:30',n:38,by:'auto'},
   {al:'下午',st:'done',t:'16:38',pt:'16:30',n:37,by:'auto'},
   {al:'晚上',st:'wait',t:'',pt:'20:30',n:0,by:''}]}, /* 3年级-1班 当天有晚上段（一天打卡 6 次三段），与考勤明细该班晚上两栏一致 */
 {k:'c33',nm:'3年级-3班',role:'任课老师',rc:'gray',total:46,segs:[
   {al:'上午',st:'done',t:'11:46',pt:'11:30',n:38,by:'auto'},
   {al:'下午',st:'delay',t:'预计 17:20',pt:'16:30',n:0,by:''}]},
 /* 3年级-4班（任课老师）仅本页为同屏展示「已放学」态而加：下午段 16:31 放学、距基准时点超 10 分钟 */
 {k:'c34',nm:'3年级-4班',role:'任课老师',rc:'gray',total:45,segs:[
   {al:'上午',st:'done',t:'11:47',pt:'11:30',n:44,by:'auto'},
   {al:'下午',st:'done',t:'16:31',pt:'16:30',n:42,by:'auto'}]},
 /* 3年级-5班（任课老师）仅本页为同屏展示「今天没有课」态而加：当天未配置班次（segs 为空） */
 {k:'c35',nm:'3年级-5班',role:'任课老师',rc:'gray',total:43,segs:[]}];
const TD_RATE=.8;
 /* 自动播报阈值：当日应到 80%（校级配置，另一口径为固定人数） */
let TD_LIVE={},tdMornOn=false,tdCloseOn=false,tdEvOn=false,tdRestMode=0,tdStyle='grid';
const TD_T0=Date.now(),TD_BASE=16*3600+44*60+5,TD_MORN_BASE=10*3600+50*60;
function tdSec(){return (tdMornOn?TD_MORN_BASE:TD_BASE)+Math.floor((Date.now()-TD_T0)/1000)}
function tdHM(){const s=tdSec(),p=n=>String(n).padStart(2,'0');return p(Math.floor(s/3600)%24)+':'+p(Math.floor(s/60)%60)}
/* 渲染用段列表：基础数据 → 形态预览叠加 → 演示内实际操作覆盖 */
/* 段的时间配置，两套时间各管各的；演示各班同别名同配置，渲染时补入。
   it / ls / le：考勤「控制时间段」——入校开始、离校时段（此间识别到通行记为出校），也是开始放学与延迟放学的时间窗；
   离校结束不单独配置：非末段 = 下一段入校开始前一分钟，末段 = 当天 23:59（tdSegs 推算）。
   pw：接送设置的「放学时间」——自动放学的计数窗口，可自由设置、可设多个，窗口内出校人数达阈值即自动放学 */
const TD_SEG_TM={上午:{it:'00:00',ls:'11:00',pw:[['11:30','12:30']]},下午:{it:'13:00',ls:'16:00',pw:[['16:20','17:30']]},晚上:{it:'17:31',ls:'20:00',pw:[['20:20','21:00']]}}; /* 与考勤明细、代学生补签同一套时段：各段首尾相接、覆盖全天（docs/考勤状态定义.md 1.1），晚上入校自 17:31 起、下午离校时段到 17:30 */
function tdHMOf(n){return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
function tdMin(hm){const [h,m]=hm.split(':').map(Number);return h*60+m}
function tdEndMin(segs,i){return tdMin(segs[i].le)}
function tdSegs(c){
  let segs=c.segs.map(s=>({...TD_SEG_TM[s.al],...s}));
  /* 上午 10:50 时点预览：全部段尚未播报、出校计数归零，主行落上午段并显示计划放学时间 */
  if(tdMornOn)segs=segs.map(s=>({...s,st:'wait',t:'',n:0,by:''}));
  /* 未播报段系统收口预览：3年级-3班 上午段离校时段结束仍未播报（未操作、未达阈值、未设延迟）→ 系统置为「未放学 · 已结束」，无播报时间，摘要行承载 */
  if(tdCloseOn&&c.k==='c33')segs=segs.map(s=>s.al==='上午'?{...s,st:'closed',t:'',by:''}:s);
  /* 第三段预览：3年级-2班追加晚托段 17:31–20:30；下午段仍未播报时主行不变、晚上沉入摘要行，下午播报后主行切至晚上段 */
  if(tdEvOn&&c.k==='c32')segs.push({...TD_SEG_TM['晚上'],al:'晚上',st:'wait',t:'',pt:'20:30',n:0,by:''});
  /* 休息日 / 无班次预览：1=3年级-3班当天无班次（混合形态）；2=休息日全部无段 */
  if(tdRestMode===2||(tdRestMode===1&&c.k==='c33'))segs=[];
  segs=segs.map((s,i)=>({...s,le:i<segs.length-1?tdHMOf(tdMin(segs[i+1].it)-1):'23:59'}));
  return segs.map(s=>TD_LIVE[c.k+s.al]?{...s,...TD_LIVE[c.k+s.al]}:s);
}
/* 主行段：自前往后取第一个仍需关注的段——未放学 / 延迟放学的段；已放学的段在「放学中」期间优先作主行，满 10 分钟转已放学后，
   还要等到下一段的入校开始时间才让给下一段（午间仍显示上午段「已放学」，不提前露出下午段）；系统收口的「未放学 · 已结束」段即时沉入摘要（与家长端同口径）；
   末段始终可作主行（全部段结束时停在最后一段） */
function tdMainIdx(segs){
  const now=Math.floor(tdSec()/60);
  for(let i=0;i<segs.length-1;i++){
    const s=segs[i];
    if(s.st==='wait'||s.st==='delay')return i;
    if(s.st==='done'&&(tdView(s)==='going'||now<tdMin(segs[i+1].it)))return i;
  }
  return segs.length-1;
}
/* -------- 高权限视图（校长 / 校级管理员）：「任教班级 / 全校班级」两个药丸 Tab --------
   tdRoleMode：0 普通教师（仅任教班级，对比预览）/ 1 高权限且带班（默认形态，与线上小程序一致：头部药丸 Tab 切「任教班级 / 全校班级」，默认停在任教班级）/ 2 高权限不带班（仅全校班级，无 Tab，对比预览）；
   全校班级复用考勤页 attSchool（22 班）并补入本页新增的任教班 3年级-5班（共 23 班），按年级分组、三列格子（班名 + 状态色 + 时间），任教班同时出现在全校班级（年级计数完整）并角标：班主任班「班主任」、其余任教班「任教」；
   格子点击与任教班级行同一分流（tdTap）；全校班级顶部为带计数的筛选 chip（全部 / 未放学 / 放学中 / 已放学；延迟放学计入未放学，没有课的班只计入全部、年级卡头不计） */
let tdRoleMode=1,tdTab='mine',tdFlt='all',tdFltMine='all',TD_SCHOOL_CACHE=null;
/* 职务管理「全体教职工」行的「智慧放学·操作」（范围全校、不带「查看」，平台默认开启）：普通教师扫本校任一班的教室放学码即可操作，页面仍只列任教班级（设计文档 13.4.4）；演示开关可模拟学校收紧后的拦截 */
let tdAllOp=true,tdViewOnly=false;
/* 全校班级表（惰性构建：attSchool 定义在本段之后）：任教班直接复用 TD_CLS 对象（操作同步），其余班按年级预置下午段演示状态；
   TD_CLS 中考勤页全校表没有的班（3年级-5班，仅本页为同屏展示「今天没有课」而加）补进所属年级，保证任教班都在全校班级里、年级计数完整 */
function tdSchool(){
  if(TD_SCHOOL_CACHE)return TD_SCHOOL_CACHE;
  const seed={'1年级':{pt:'16:20',st:['done','done','done','done'],t:['16:21','16:23','16:22','16:25']},
    '2年级':{pt:'16:30',st:['done','done','done','done'],t:['16:36','16:38','16:40','16:37']},
    '3年级':{pt:'16:30',st:['wait','wait','wait','wait'],t:['','','','']},
    '4年级':{pt:'16:40',st:['wait','wait','delay','wait'],t:['','','预计 17:00','']},
    '5年级':{pt:'16:45',st:['wait','wait','wait'],t:['','','']},
    '6年级':{pt:'16:50',st:['wait','delay','wait'],t:['','预计 17:10','']}};
  TD_SCHOOL_CACHE=attSchool.map(gr=>{
    const g=parseInt(gr.g,10),sd=seed[gr.g];
    return {g:gr.g,cls:gr.cls.map((c,i)=>{
      const n=+c.n.match(/-(\d+)班/)[1],k='c'+g+n,own=TD_CLS.find(x=>x.k===k);
      if(own)return own;
      return {k,nm:c.n,role:'',rc:'gray',total:c.t,segs:[
        {al:'上午',st:'done',t:'11:4'+(i+4),pt:g==='3年级'?'11:30':'11:40',n:c.t-1,by:'auto'}, /* 3年级与任教班同一班次（放学 11:30 / 16:30） */
        {al:'下午',st:sd.st[i],t:sd.t[i],pt:sd.pt,n:0,by:sd.st[i]==='done'?'auto':''}]};
    })};
  });
  const no=c=>+c.nm.match(/-(\d+)班/)[1];
  TD_CLS.forEach(c=>{const gr=TD_SCHOOL_CACHE.find(x=>c.nm.startsWith(x.g));if(gr&&!gr.cls.includes(c)){gr.cls.push(c);gr.cls.sort((a,b)=>no(a)-no(b))}});
  return TD_SCHOOL_CACHE;
}
/* 第二个 Tab 的班级：「查看」范围的并集（含任教班级）。全校范围为全校班级；预览 3 为任教班级所在年级 ∪ 4年级 */
function tdScopeGrades(){const all=tdSchool();return tdRoleMode===3?all.filter(g=>g.g==='3年级'||g.g==='4年级'):all}
function tdAllCls(){const m=new Map();TD_CLS.forEach(c=>m.set(c.k,c));if(tdRoleMode)tdSchool().forEach(g=>g.cls.forEach(c=>m.set(c.k,c)));return [...m.values()]}
/* 摘要行单段文案：未播报段印计划放学时间（与主行同口径，避免「下午 未放学」读成漏放），其余段印播报 / 预计时间 + 状态 */
function tdRestTxt(s){return s.st==='wait'?s.al+' '+s.pt+' 放学':s.al+(s.t?' '+s.t:'')+' '+TD_ST[tdView(s)][0]}
/* 任教班级紧凑行（每班一行，对比预览，tdStyle='row'）：首行左侧班名 + 主行段别名、右侧状态 chip + 时间 + 箭头；次行通栏为角色 chip + 其余段摘要（超长省略）；
   行 id 沿用 td-card-*（扫教室放学码落页按 id 滚动定位），点击与原班级卡主行同一分流（tdTap） */
function tdRow(c){
  const segs=tdSegs(c),sub=rs=>'<div class="sub"><span class="chip '+c.rc+' plain">'+c.role+'</span>'+(rs?'<span class="rs">'+rs+'</span>':'')+'</div>';
  if(!segs.length)return '<div class="td-row rd" id="td-card-'+c.k+'" onclick="tdTap(\''+c.k+'\')"><div class="nm"><b>'+c.nm+'</b></div><span class="none">今天没有课</span><span class="arr ghost">›</span>'+sub('')+'</div>';
  const mi=tdMainIdx(segs),m=segs[mi],rest=segs.filter((_,i)=>i!==mi),v=tdView(m),op=m.st==='wait'||m.st==='delay';
  const tm=m.st==='wait'?'<span class="tm plan">'+m.pt+' 放学</span>':'<span class="tm">'+(m.st==='closed'?'':m.t)+'</span>'; /* 收口段输出空时间列，保持列宽对齐 */
  return '<div class="td-row '+(op?'op':'rd')+'" id="td-card-'+c.k+'" onclick="tdTap(\''+c.k+'\')"><div class="nm"><b>'+c.nm+'</b><span class="al">'+m.al+'</span></div>'+
   '<span class="dis-st '+TD_ST[v][1]+'">'+TD_ST[v][0]+'</span>'+tm+'<span class="arr'+(op?'':' ghost')+'">›</span>'+sub(rest.map(tdRestTxt).join('　·　'))+'</div>';
}
/* 原班级卡样式（对比预览，tdStyle='card'）：卡头班名 + 角色 chip，卡内主行 + 摘要行 */
function tdCard(c){
  const segs=tdSegs(c);
  const hd='<div class="td-cls-hd"><b>'+c.nm+'</b><span class="chip '+c.rc+' plain">'+c.role+'</span></div>'; /* 已去除卡头「应到 N 人」（c.total 仍供阈值计算） */
  if(!segs.length)return '<div class="dis-card" id="td-card-'+c.k+'">'+hd+'<div class="td-body"><div class="dn-main rd" onclick="tdTap(\''+c.k+'\')"><span class="none">今天没有课</span></div></div></div>';
  const mi=tdMainIdx(segs),m=segs[mi],rest=segs.filter((_,i)=>i!==mi);
  const tm=m.st==='wait'?'<span class="tm plan">'+m.pt+' 放学</span>':m.st==='closed'?'<span class="tm"></span>':'<span class="tm">'+m.t+'</span>'; /* 收口段也输出空时间列，保持列宽对齐 */
  /* 未放学 / 延迟段：主行可点，拉起「放学确认」半屏（参考 tn 原型）；卡内不再放操作按钮（原 td-act 已去除） */
  const op=m.st==='wait'||m.st==='delay';
  return '<div class="dis-card" id="td-card-'+c.k+'">'+hd+'<div class="td-body">'+
   '<div class="dn-main '+(op?'op':'rd')+'" onclick="tdTap(\''+c.k+'\')"><span class="al">'+m.al+'</span><span class="dis-st '+TD_ST[tdView(m)][1]+'">'+TD_ST[tdView(m)][0]+'</span>'+tm+'<span class="arr'+(op?'':' ghost')+'">›</span></div>'+ /* 不可点行箭头占位不显示，保证各行网格一致 */
   /* 已去除出校计数区块（进度条 + 「已出校 n / N · 百分比」+ 触发方式文案）：计数与阈值仅在后台驱动自动播报，不上屏 */
   (rest.length?'<div class="dn-rest">'+rest.map(tdRestTxt).join('　·　')+'</div>':'')+
  '</div></div>';
}
/* 全校格子的汇总态：wait（含 delay / closed）/ going / done / none */
function tdTileSt(c){const m=tdMain(c.k);if(!m)return 'none';const v=tdView(m);return v==='going'||v==='done'?v:'wait'}
/* 班级格子：mine=任教班级（默认格子样式）——角标改印「班主任」（任教班里人人都是任教，「任教」角标无区分度）；否则为全校班级，兼带班账号的任教班角标：班主任班印「班主任」（与任教班级 Tab 同一称呼）、其余任教班印「任教」，非任教班不印 */
function tdTile(c,mine){
  const m=tdMain(c.k),v=m?tdView(m):'none';
  const cls=!m?'none':v==='going'?'going':v==='done'?'done':m.st==='delay'?'delay':'wait';
  const sub=!m?'没有课':v==='going'||v==='done'?m.t:m.st==='delay'?m.t:m.st==='closed'?'已结束':m.pt+' 放学';
  const own=TD_CLS.some(x=>x.k===c.k),tag=mine?(c.role==='班主任'?'<span class="tg">班主任</span>':''):((tdRoleMode===1||tdRoleMode===3)&&own?'<span class="tg">'+(c.role==='班主任'?'班主任':'任教')+'</span>':'');
  return '<div class="td-tile '+cls+'" id="td-tile-'+c.k+'" data-st="'+tdTileSt(c)+'" onclick="tdTap(\''+c.k+'\')">'+c.nm+'<small>'+sub+'</small>'+tag+'</div>';
}
/* 年级分组格子区（全校班级与任教班级默认格子样式共用，保证两边同一布局）：带计数与状态色点的筛选 chip + 年级卡（卡头计数）+ 三列格子；
   原「全校三态汇总」一行并入筛选 chip，色点兼作图例；没有课的班只计入「全部」（不单设 chip，避免一行放不下折成两行），年级卡头也不计「没有课」（格子本身灰底印「没有课」已足够）；年级内全部班都没有课时卡头改印「今天没有课」，避免出现三个 0 */
function tdGridHtml(grades,flt,fn,mine){
  const all=grades.flatMap(g=>g.cls),n={wait:0,going:0,done:0,none:0};all.forEach(c=>n[tdTileSt(c)]++);
  const fl=[['all','全部',all.length],['wait','未放学',n.wait],['going','放学中',n.going],['done','已放学',n.done]];
  let h='<div class="fchips td-flt">'+fl.map(f=>'<button class="fchip'+(flt===f[0]?' on':'')+'" onclick="'+fn+'(\''+f[0]+'\')">'+(f[0]==='all'?'':'<i class="'+f[0]+'"></i>')+f[1]+' '+f[2]+'</button>').join('')+'</div>'+
   grades.map(g=>{
     const cs=g.cls.filter(c=>flt==='all'||tdTileSt(c)===flt);
     if(!cs.length)return '';
     const gn={wait:0,going:0,done:0,none:0};g.cls.forEach(c=>gn[tdTileSt(c)]++);
     return '<div class="dis-card td-grade"><div class="td-cls-hd"><b>'+g.g+'</b><small>'+(gn.none===g.cls.length?'今天没有课':'未放学 '+gn.wait+' · 放学中 '+gn.going+' · 已放学 '+gn.done)+'</small></div><div class="td-grid">'+cs.map(c=>tdTile(c,mine)).join('')+'</div></div>';
   }).join('');
  if(flt!=='all'&&!n[flt])h+='<div class="dis-card"><div class="td-body"><div class="dn-main"><span class="none">没有'+{wait:'未放学',going:'放学中',done:'已放学'}[flt]+'的班级</span></div></div></div>';
  return h;
}
/* 任教班级排序与全校班级同一规则：年级按入学年份倒序、年级内按班号升序（班主任班不再排首位，靠角标区分——同一张年级卡在两个 Tab 下格子顺序一致，切 Tab 不用重新定位）；
   三种样式（格子 / 紧凑行 / 原班级卡）共用此顺序，TD_CLS 本身的顺序仅供数据定义 */
function tdClsNo(c){return +c.nm.match(/-(\d+)班/)[1]}
function tdMineSorted(){return [...TD_CLS].sort((a,b)=>parseInt(a.nm,10)-parseInt(b.nm,10)||tdClsNo(a)-tdClsNo(b))}
/* 任教班级按年级分组（默认格子样式用）：年级取班名前缀 */
function tdMineGrades(){
  const m=new Map();tdMineSorted().forEach(c=>{const g=c.nm.split('-')[0];if(!m.has(g))m.set(g,[]);m.get(g).push(c)});
  return [...m].map(([g,cls])=>({g,cls}));
}
const TD_EMPTY_ICO='<svg width="56" height="56" viewBox="0 0 24 24" fill="none" stroke="#D5DAE4" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round"><rect x="3.5" y="5" width="17" height="15.5" rx="2.2"/><path d="M8 3v4M16 3v4M3.5 10h17"/><path d="M9.5 15.3h5"/></svg>';
/* 页面渲染：tdRoleMode 0 → 任教班级；1（默认）→ 头部药丸 Tab 切「任教班级 / 全校班级」（tdTab）；2 → 仅全校班级。
   当前列表的班级当天全部没有班次（休息日即其特例，不做独立判定）→ 页面级空态代替逐班「今天没有课」；
   「点击班级，可进行放学操作」提示仅在当前列表存在未放学 / 延迟放学的班级时显示 */
function tdRender(){
  if(noClsOn('dis')){/* 持有「智慧放学 · 查看」但范围内无班级（noClsTog）：与只有「操作」的账号（tdRoleMode 4）相同——首页不显示宫格，只能扫教室放学码进入；Tab、操作提示不显示，列表为空态 */
    document.getElementById('td-tabs').style.display='none';document.getElementById('td-tip').style.display='none';
    document.getElementById('td-list').innerHTML='<div class="td-empty">'+TD_EMPTY_ICO+'<p>暂无可查看的班级</p></div>';return;
  }
  const tabs=tdRoleMode===1||tdRoleMode===3,mine=tdRoleMode===0||(tabs&&tdTab==='mine');
  document.getElementById('td-tabs').style.display=tabs?'':'none';
  document.querySelector('#td-tabs button[data-tb="school"]').textContent=tdRoleMode===3?'可查看班级':'全校班级'; /* 第二个 Tab 按查看范围命名：全校为「全校班级」，否则「可查看班级」 */
  document.querySelectorAll('#td-tabs button').forEach(b=>b.classList.toggle('on',b.dataset.tb===(mine?'mine':'school')));
  const grades=mine||tdRoleMode===4?null:tdScopeGrades(),vis=tdRoleMode===4?[]:mine?TD_CLS:grades.flatMap(g=>g.cls);
  /* 操作提示：当前 Tab 存在本人可操作、主行段为未放学 / 延迟放学的班级时才显示 */
  document.getElementById('td-tip').style.display=vis.some(c=>{const m=tdMain(c.k);return m&&(m.st==='wait'||m.st==='delay')&&tdCanOp(c.k)})?'':'none';
  let h;
  if(tdRoleMode===4)h='<div class="td-empty">'+TD_EMPTY_ICO+'<p>暂无可查看的班级</p></div>'; /* 没有任何「查看」：经扫码进入，列表为空 */
  else if(!vis.some(c=>tdSegs(c).length))h='<div class="td-empty">'+TD_EMPTY_ICO+'<p>今天没有课</p></div>';
  else if(mine)h=tdStyle==='grid'?tdGridHtml(tdMineGrades(),tdFltMine,'tdFilterMine',true):tdStyle==='card'?tdMineSorted().map(tdCard).join(''):'<div class="dis-card td-rows">'+tdMineSorted().map(tdRow).join('')+'</div>';
  else h=tdGridHtml(grades,tdFlt,'tdFilter',false); /* 不带班账号不再印「全校班级」区块标题（旧两区块布局残留）：筛选 chip「全部 23」与六张年级卡已说明范围，页面结构与普通教师视角相同 */
  document.getElementById('td-list').innerHTML=h;
}
/* 筛选：全校班级与任教班级「格子」样式各自独立（切 Tab 互不影响） */
function tdFilter(f){tdFlt=f;tdRender()}
function tdFilterMine(f){tdFltMine=f;tdRender()}
/* 高权限兼带班：药丸 Tab 切换「任教班级 / 全校班级」，切换后回到列表顶部 */
function tdTabSw(t){tdTab=t;document.querySelector('#sc-dismiss .body').scrollTop=0;tdRender()}
/* 角色切换：0 普通教师（对比预览）/ 1 高权限且带班（默认）/ 2 高权限不带班（对比预览） */
function tdRole(mode){
  tdRoleMode=mode;tdTab='mine';tdFlt=tdFltMine='all';tdHomeSync();
  if(curScreen!=='sc-dismiss')go('sc-dismiss');
  document.querySelector('#sc-dismiss .body').scrollTop=0;
  tdRender();
  demoToast(['已切换为普通教师视角（对比）：仅任教班级','已恢复高权限账号（兼带班，默认）：「任教班级 / 全校班级」两个 Tab','已切换为高权限账号（不带班，对比）：仅全校班级','已切换为4年级年级组长兼 3年级任教：「任教班级 / 可查看班级」两个 Tab','已切换为只有「操作」的账号：首页不显示智慧放学，扫教室放学码进入'][mode]);
}
/* 任教班级样式：grid 格子（默认，与全校班级同一布局：带计数筛选 chip + 年级卡三列格子）/ row 紧凑行（对比预览）/ card 原「班级卡 × 班次段」（对比预览） */
function tdStyleSet(s){
  if(tdRoleMode===2||tdRoleMode===4){demoToast('当前账号没有任教班级，请先切回普通教师或兼带班视角');return}
  tdStyle=s;tdTab='mine';tdFltMine='all';
  if(curScreen!=='sc-dismiss')go('sc-dismiss');
  document.querySelector('#sc-dismiss .body').scrollTop=0;
  tdRender();
  demoToast({grid:'已恢复格子样式（默认）：与全校班级同一布局',row:'已切换为紧凑行样式（对比）',card:'已切换为原班级卡样式（对比）'}[s]);
}
/* 操作权限（按「智慧放学·操作」权限点判定，与「查看」独立）：普通教师仅任教班级；高权限账号可操作全校任一班级；学校为全体教职工开启「操作」后（tdAllOp）普通教师也可操作全校任一班级 */
/* tdRoleMode 3（预览）：4年级年级组长兼 3年级任教——「查看」「操作」范围 = 任教班级 ∪ 4年级；tdRoleMode 4（预览）：没有任何「查看」、只有全体教职工「操作」的账号（如后勤人员）；
   tdViewOnly（预览开关）：任教之外的范围只有「查看」没有「操作」（同时模拟学校去掉全体教职工的「操作」，否则全校班级本就可操作） */
function tdOwn(k){return tdRoleMode!==2&&tdRoleMode!==4&&TD_CLS.some(c=>c.k===k)}
function tdInScope(k){return tdRoleMode===1||tdRoleMode===2||(tdRoleMode===3&&/^c4\d+$/.test(k))}
function tdCanView(k){return tdOwn(k)||tdInScope(k)}
function tdCanOp(k){return tdAllOp||tdOwn(k)||(tdInScope(k)&&!tdViewOnly)}
function tdViewOnlyToggle(){
  tdViewOnly=!tdViewOnly;tdAllOp=!tdViewOnly;
  if(tdRoleMode===0||tdRoleMode===4){tdRoleMode=1;tdTab='school';tdFlt=tdFltMine='all';tdHomeSync()}
  if(curScreen!=='sc-dismiss')go('sc-dismiss');
  tdRender();
  demoToast(tdViewOnly?'已模拟：全校班级只有「查看」没有「操作」，点未放学的班提示暂无操作权限':'已恢复：全校班级可查看可操作');
}
/* 首页宫格「智慧放学」：没有「查看」、或「查看」范围内没有班级的账号不显示（只经扫教室放学码进入本页操作）；tdRoleMode 4 为演示视角「只有操作」 */
function tdHomeSync(){const b=document.getElementById('hm-dismiss');if(b)b.style.display=tdRoleMode===4||(typeof DS!=='undefined'&&DS&&!meCanSee('dis.view'))?'none':''}
function tdAllOpToggle(){tdAllOp=!tdAllOp;if(tdAllOp)tdViewOnly=false;demoToast(tdAllOp?'已恢复默认：全体教职工带「智慧放学·操作」，扫码可操作本校任一班':'已模拟：学校已去掉全体教职工的「智慧放学·操作」，扫本校非任教班码将被拦')}
/* 以指定视角扫教室放学码（0 普通教师 / 1 兼带班高权限 / 2 不带班高权限），演示「只有操作、没有查看」的班级经扫码进入 */
function tScanDismissAs(mode,k){tdRoleMode=mode;tdTab='mine';tdFlt=tdFltMine='all';tdHomeSync();tScanDismiss(k)}
function tdCls(k){return TD_CLS.find(c=>c.k===k)||(tdRoleMode?tdAllCls().find(c=>c.k===k):tdSchool().flatMap(g=>g.cls).find(c=>c.k===k))}
function tdMain(k){const c=tdCls(k),segs=tdSegs(c);if(!segs.length)return null;return segs[tdMainIdx(segs)]}
function tdHMS(){const s=tdSec(),p=n=>String(n).padStart(2,'0');return p(Math.floor(s/3600)%24)+':'+p(Math.floor(s/60)%60)+':'+p(s%60)}
/* 放学确认半屏（参考 tn 原型 dmConfirm）：延迟提示 + 当前班级（不印班次段，操作对象即主行段）+ 圆形「开始放学」大按钮（内含实时时钟）+ 底部「延迟放学 / 调整延迟」与「取消」 */
function tdOpen(k){
  const c=tdCls(k),m=tdMain(k);
  if(curScreen!=='sc-dismiss')go('sc-dismiss');
  if(!m){toast(c.nm+' 今天没有班次');return}
  if(m.st==='done'){toast(c.nm+' '+m.al+'段已于 '+m.t+' 放学');return}
  if(m.st==='closed'){toast(c.nm+' '+m.al+'段离校时段已结束');return}
  const dl=m.st==='delay';
  sheet('<div class="tdf-hd"><b>放学确认</b><button class="tdf-x" onclick="closeSheet()"><svg width="12" height="12" viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M2 2l8 8M10 2l-8 8"/></svg></button></div>'+
    '<div class="tdf-hint"><i>!</i>如果延迟放学，则延迟放学时间到后将自动放学</div>'+
    '<div class="tdf-cls">当前班级：<span>'+c.nm+'</span></div>'+
    (dl?'<div class="tdf-dl">已延迟至 '+m.t.replace('预计 ','')+' 放学</div>':'')+
    '<div class="tdf-start-wrap"><button class="tdf-start" onclick="tdBroadcast(\''+k+'\')"><b>开始放学</b><span id="tdf-time">'+tdHMS()+'</span></button></div>'+
    '<div class="tdf-foot"><button class="dl" onclick="tdDelaySheet(\''+k+'\')">'+(dl?'调整延迟':'延迟放学')+'</button><button class="cx" onclick="closeSheet()">取消</button></div>');
}
/* 主行点击统一入口：未放学 / 延迟段拉起放学确认半屏；放学中 / 已放学 / 已结束 / 无班次只给一条轻反馈 toast、不拉半屏（扫教室放学码落页后走同一分流）；
   放学中（开始放学后 10 分钟内）toast 写「HH:MM 开始放学」，与行内 chip 同口径，不说「已放学」 */
function tdTap(k){
  const c=tdCls(k),m=tdMain(k);
  if(!m){toast(c.nm+' 今天没有课');return}
  if(m.st==='wait'||m.st==='delay'){if(!tdCanOp(k)){toast('暂无 '+c.nm+' 的放学操作权限');return}tdOpen(k);return}
  if(m.st==='closed'){toast(c.nm+' '+m.al+'段离校时段已结束');return}
  toast(c.nm+' '+m.t+(tdView(m)==='going'?' 开始放学':' 已放学'));
}
/* 开始放学（半屏主按钮）：主行段置为已放学（10 分钟内展示为「放学中」）、时间取当前时钟；指令下发在线音屏、家长端同步推送班级放学通知——
   系统细节不上屏，toast 只说老师关心的结果（与行内「放学中」同口径） */
function tdBroadcast(k){
  const c=tdCls(k),m=tdMain(k);
  if(curScreen!=='sc-dismiss')go('sc-dismiss');
  if(!m){toast(c.nm+' 今天没有班次');return}
  if(m.st==='done'){toast(c.nm+' '+m.al+'段已于 '+m.t+' 放学');return}
  if(Math.floor(tdSec()/60)<tdMin(m.ls)){toast(c.nm+' '+m.al+'段 '+m.ls+' 后可开始放学');return} /* 离校开始前不可开始放学（离校时段结束后该段已收口，不再是可操作状态；末段离校结束为 23:59） */
  TD_LIVE[k+m.al]={st:'done',t:tdHM(),by:'manual'};
  closeSheet();tdRender();
  toast(c.nm+' 已开始放学，已通知家长');
}
/* 出校计数达阈值（自动通道）：计数补到阈值；未播报 / 延迟段即自动播报，已手动播报的段只更新计数、不重播 */
function tdAutoHit(k){
  const c=tdCls(k),m=tdMain(k),need=Math.ceil(c.total*TD_RATE);
  if(curScreen!=='sc-dismiss')go('sc-dismiss');
  if(!m){toast(c.nm+' 今天没有班次');return}
  const now=Math.floor(tdSec()/60);
  if(m.st!=='done'&&!m.pw.some(([a,b])=>now>=tdMin(a)&&now<=tdMin(b))){toast('不在'+m.al+'段放学时间内');return} /* 只统计接送设置「放学时间」内的出校 */
  const n=Math.max(m.n,need);
  if(m.st==='done'){TD_LIVE[k+m.al]={...(TD_LIVE[k+m.al]||{st:'done',t:m.t,by:m.by}),n};tdRender();toast('该段已'+(m.by==='manual'?'手动':'自动')+'播报');return}
  TD_LIVE[k+m.al]={st:'done',t:tdHM(),by:'auto',n};
  tdRender();
  toast('出校 '+n+' 人，已自动播报');
}
/* 延迟放学：从放学确认半屏进入，时 / 分两列滚轮选预计放学时间（暂不填原因），确定后家长端主行转「延迟放学 预计 HH:MM」并推送延迟通知；取消回到放学确认半屏。
   可选下限 = 当前时间与该段计划放学时间中较晚者的下一分钟（延迟相对计划而言，不能早于计划；上午时点下计划 11:30，原「当前 +10 分钟」默认值会落到 11:00）；
   小时列自下限所在小时起，选中该小时时分钟列自下限分钟起、其余小时 00–59（与微信原生 picker mode="time" 设 start 后一致）；
   默认值：延迟态取当前延迟时间，否则取「当前时间与计划放学时间中较晚者」+10 分钟 */
const TD_HOURS=Array.from({length:24},(_,i)=>String(i).padStart(2,'0')),TD_MINS=Array.from({length:60},(_,i)=>String(i).padStart(2,'0'));
let tdDlLo=0,tdDlHi=1439;
 /* 当前延迟滚轮的可选下限（当天分钟数） */
function tdDelayLo(m){const [h,mm]=m.pt.split(':').map(Number);return Math.max(Math.floor(tdSec()/60),h*60+mm)+1}
function tdWheelInit(id,idx){const w=document.getElementById(id);w.addEventListener('scroll',()=>wheelPaint(w));w.scrollTop=idx*36;wheelPaint(w)}
function tdWheelSel(id,len){return Math.min(Math.max(Math.round(document.getElementById(id).scrollTop/36),0),len-1)}
function tdDlHour(){const lh=Math.floor(tdDlLo/60);return lh+tdWheelSel('td-wh',Math.floor(tdDlHi/60)-lh+1)}
function tdDlMin(){const w=document.getElementById('td-wm');return +w.dataset.off+tdWheelSel('td-wm',+w.dataset.len)}
/* 分钟列随小时联动：仅在「是否为下限所在小时」切换时重建，尽量保持原分钟值（低于下限则落到下限） */
function tdDlMins(keep){
  const w=document.getElementById('td-wm'),h=tdDlHour(),off=h===Math.floor(tdDlLo/60)?tdDlLo%60:0,end=h===Math.floor(tdDlHi/60)?tdDlHi%60:59;
  if(w.dataset.key===off+'-'+end)return;
  if(keep===undefined)keep=tdDlMin();
  w.dataset.off=off;w.dataset.len=end-off+1;w.dataset.key=off+'-'+end;w.innerHTML=wheelItems(TD_MINS.slice(off,end+1).map(x=>x+'分'));
  w.scrollTop=(Math.min(Math.max(keep,off),end)-off)*36;wheelPaint(w);
}
function tdDelaySheet(k){
  const c=tdCls(k),m=tdMain(k);
  if(curScreen!=='sc-dismiss')go('sc-dismiss');
  if(!m){toast(c.nm+' 今天没有班次');return}
  if(m.st==='done'){toast(m.al+'段已放学，无法延迟');return}
  const lo=tdDelayLo(m),segs=tdSegs(c),mi=tdMainIdx(segs),last=mi===segs.length-1,hi=tdEndMin(segs,mi); /* 上限：该段离校时段结束（末段为 23:59） */
  if(lo>hi){toast(last?'今天已无法延迟放学':m.al+'段即将结束，无法延迟');return}
  let v;
  if(m.st==='delay'){const [h,mm]=m.t.replace('预计 ','').split(':').map(Number);v=h*60+mm}
  else v=lo-1+10;
  v=Math.min(Math.max(v,lo),hi);tdDlLo=lo;tdDlHi=hi;
  /* 形态：居中标题 + 右上 ×（关闭整个流程）；时 / 分两列滚轮、项内带单位、分隔线通栏；底部绿色描边「取消」（回放学确认半屏）与绿色实底「确定」胶囊按钮 */
  sheet('<div class="tdd-hd"><b>选择延迟放学时间</b><button class="tdf-x" onclick="closeSheet()"><svg width="12" height="12" viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M2 2l8 8M10 2l-8 8"/></svg></button></div>'+
    '<div class="wheelbox tdd-wheel"><div class="wheel" id="td-wh">'+wheelItems(TD_HOURS.slice(Math.floor(lo/60),Math.floor(hi/60)+1).map(h=>h+'时'))+'</div><div class="wheel" id="td-wm"></div></div>'+
    '<div class="tdd-foot"><button class="cancel" onclick="tdOpen(\''+k+'\')">取消</button><button class="ok" onclick="tdDelaySet(\''+k+'\')">确定</button></div>');
  tdWheelInit('td-wh',Math.floor(v/60)-Math.floor(lo/60));
  tdDlMins(v%60);
  const wm=document.getElementById('td-wm');wm.addEventListener('scroll',()=>wheelPaint(wm));
  document.getElementById('td-wh').addEventListener('scroll',()=>tdDlMins());
}
function tdDelaySet(k){
  const c=tdCls(k),m=tdMain(k);
  const hi=tdDlHour(),mi=tdDlMin(),t=TD_HOURS[hi]+':'+TD_MINS[mi],[ph,pm]=m.pt.split(':').map(Number);
  if(hi*3600+mi*60<=tdSec()){toast('需晚于当前时间');return} /* 滚轮打开期间时钟仍在走，下限可能被追上 */
  if(hi*60+mi<=ph*60+pm){toast('需晚于计划放学时间');return}
  TD_LIVE[k+m.al]={st:'delay',t:'预计 '+t,by:''};
  closeSheet();tdRender();
  toast('已延迟放学，已通知家长');
}
