let lvRoleMode=1;
 /* 1 班主任（默认）/ 0 纯任课老师 / 2 校长不带班（全校范围、无审批职责）；0 与 2 均无 tab（lv-solo） */
const LV_FLT={
  cls:{t:'选择班级',h:'班级',all:'全部班级',opts:()=>lvRoleMode===2?SCHOOL_CLS.map(c=>[c.full,c.full,'']):plClasses.filter(c=>lvRoleMode||c.r!=='班主任').map(c=>[c.c,c.c,c.r])},
  ty:{t:'选择请假类型',h:'请假类型',all:'全部类型',opts:()=>[['病假','病假'],['事假','事假']]},
  /* 第一阶段隐藏「退回补充」状态（后续阶段，与家长端 LV_STATES 同口径；恢复详情页「退回补充」按钮时在「待审批」后加回） */
  st:{t:'选择审批状态',h:'审批状态',all:'全部状态',opts:()=>['待审批','销假待确认','已通过','已销假','已撤销','未通过'].map(x=>[x,x])}
};
function lvFltSheet(k){
  const f=LV_FLT[k];
  /* 类型 / 状态半屏头部：居中标题 + 右上关闭（.flt-hd） */
  const hd='<div class="flt-hd"><h3>'+f.h+'</h3><button class="flt-x" onclick="closeSheet()" aria-label="关闭">✕</button></div>';
  if(k==='cls'){/* 班级：原生多列 picker（年级 | 班级，clsWheelSheet），候选集随视角（任教班级 / 校长全校），左列首项「全部班级」 */
    const list=lvRoleMode===2?SCHOOL_CLS:plClasses.filter(c=>lvRoleMode||c.r!=='班主任').map(c=>{const m=c.c.match(/(\d)年级-(\d+)班/);return{g:+m[1],n:+m[2],full:c.c}});
    clsWheelSheet(list,lvF.cls,true,it=>lvFltPick('cls',it==='all'?'all':it.full));return;
  }
  /* 请假类型 / 审批状态：居中标题 + 右上关闭 + 胶囊单选，点选即生效 */
  const chip=(v,label)=>'<button class="flt-chip'+(lvF[k]===v?' on':'')+'" onclick="lvFltPick(\''+k+'\',\''+v+'\')">'+label+'</button>';
  sheet(hd+'<div class="flt-chips">'+chip('all','全部')+f.opts().map(o=>chip(o[0],o[1])).join('')+'</div>');
}
