function lvTabPick(t){lvF.tab=t;lvF.cls='all';lvF.ty='all';lvF.st='all';lvFltApply()}
/* -------- 首页宫格待办角标（2026-10-26 定）：请假 / 学生管理 / 教师管理三个宫格显示本人需处理的事项数，与各页待办角标同源同数（请假页「待我审批」、学生管理「待审核」、教师管理「待审核」），
   处理后即时递减、为 0 隐藏、超过 99 显示 99+；只计本人队列——待办只派班主任（lvRoleMode 1），校长 / 纯任课老师视角请假宫格不显示角标。
   智能校徽宫格同样有角标（2026-10-26 同日纠正）：数字 = 信息确认页「待确认」数（老师核对家长提交信息的本人队列，apWaitSync 按名单行计数），「未提交」是家长尚未提交、只能提醒，不计；素质评价、校园签到、智慧放学等无本人队列，不加 -------- */
function hmSet(k,n){(window.__hm||(window.__hm={}))[k]=n;homeBadgeUpd()}
function homeBadgeUpd(){
  const h=window.__hm||{};
  /* 教师管理宫格按「教师管理·查看」显隐（2026-11-04）；无功能权限预览另行整体隐藏宫格 */
  const tg=document.getElementById('hm-badge-tch');if(tg&&typeof DS!=='undefined'&&DS)tg.parentNode.style.display=meTch('tch.view')?'':'none';
  /* 智能校徽（含活动横幅）、校园签到、学生管理、素质评价、请假宫格：持有该模块「查看」权限点、且按范围至少覆盖一个班才显示（meCanSee，2026-11-11 与研发确认，PRD 2.1.1.12 第 2 条）；
     持有但范围内没有班级、或只有操作类权限点（如只有「素质评价 · 点评」）的不显示；智慧放学见 tdHomeSync。演示账号王老师各项都持有且有班级，页面上不变 */
  if(typeof DS!=='undefined'&&DS){
    const show=(el,p)=>{if(el)el.style.display=meCanSee(p)?'':'none'};
    const ab=document.getElementById('hm-badge-apply');show(ab&&ab.parentNode,'badge.view');
    if(!homeNoPerm)show(document.getElementById('home-banner'),'badge.view');
    show(document.getElementById('gi-att'),'att.view');
    const sb=document.getElementById('hm-badge-stu');show(sb&&sb.parentNode,'stu.view');
    show(document.getElementById('gi-eval'),'eva.view');
    const lg=document.getElementById('hm-badge-leave');show(lg&&lg.parentNode,'leave.view');
    tdHomeSync();
  }
  [['badge','hm-badge-apply'],['leave','hm-badge-leave'],['stu','hm-badge-stu'],['tch','hm-badge-tch']].forEach(([k,id])=>{
    const e=document.getElementById(id);if(!e)return;const n=h[k]||0;
    e.textContent=n>99?'99+':n;e.style.display=n?'':'none';
  });
}
function lvFltApply(){
  document.getElementById('sc-leave').classList.toggle('lv-solo',lvRoleMode!==1);
  document.querySelector('#sc-leave .apply-foot').style.display='';/* 代学生请假按「请假 · 代请假」权限点显示：班主任、任课老师与校长（默认模板持有）均可见，无处理资格的代请转该班班主任审批（2026-10-21） */
  document.querySelectorAll('#lv-tabs button').forEach((b,i)=>b.classList.toggle('on',(i===0?'mine':'all')===lvF.tab));
  document.getElementById('lv-flt').style.display=lvF.tab==='all'?'':'none';
  ['cls','ty','st'].forEach(k=>{const b=document.getElementById('lv-flt-'+k);b.textContent=(lvF[k]==='all'?LV_FLT[k].all:lvF[k])+' ▾';b.classList.toggle('on',lvF[k]!=='all')});
  const q=(document.getElementById('lv-q').value||'').trim();
  const scope=LV_FLT.cls.opts().map(o=>o[0]);/* 列表范围 = 本人任教班级（纯任课老师预览仅任课班级；校长视角为全校） */
  const pendSt=r=>r.st==='待审批'||r.st==='销假待确认';
  const all=lvRecs().filter(r=>scope.includes(r.cls));
  /* 待我审批角标只计本人担任班主任、持有「审批与销假确认」的班级中的待审批 + 销假待确认（按队列总数计，不受姓名搜索影响） */
  const mine=all.filter(r=>pendSt(r)&&lvHeadCls(r.cls)).length,gb=document.getElementById('lv-mine-n');gb.textContent=mine;gb.style.display=mine?'':'none';hmSet('leave',lvRoleMode===1?mine:0);
  const ok=r=>(lvF.tab==='all'||(pendSt(r)&&lvHeadCls(r.cls)))&&(!q||r.name.includes(q))&&(lvF.cls==='all'||r.cls===lvF.cls||r.cls.startsWith(lvF.cls+'-'))&&(lvF.ty==='all'||r.ty===lvF.ty)&&(lvF.st==='all'||r.st===lvF.st);
  /* 待处理单在前、按提交时间正序（销假待确认按申请销假时间，先提交先处理）；已办结单按最近一次处理时间倒序，同刻生成的代请单按姓名拼音 */
  const pendKey=r=>r.st==='销假待确认'?(r.tl.slice().reverse().find(x=>x.n==='申请销假')||{}).at||r.tm:r.tm;
  const lastAt=r=>r.tl.reduce((m,x)=>x.at&&x.at>m?x.at:m,'');
  const pend=all.filter(r=>pendSt(r)&&ok(r)).sort((a,b)=>pendKey(a).localeCompare(pendKey(b)));
  const done=all.filter(r=>!pendSt(r)&&ok(r)).sort((a,b)=>lastAt(b).localeCompare(lastAt(a))||stuColl.compare(a.name,b.name));
  document.getElementById('lv-pend').innerHTML=pend.map(lvCardHTML).join('');
  document.getElementById('lv-done').innerHTML=done.map(lvCardHTML).join('');
  const n=pend.length+done.length;
  document.getElementById('lv-empty').style.display=n?'none':'';
  /* 空态文案：两个页签、有无搜索 / 筛选一律「暂无请假单」（PRD 2.1.4.8 第 7 条） */
  document.getElementById('lv-empty-t').textContent='暂无请假单';
}
