function sevRender(){
  sevMap=[];
  if(sevLimited){document.getElementById('sev-list').innerHTML='';return} /* 无该生「查看」：本页不列记录，本人刚提交的点评同样不显示 */
  let html='';
  document.querySelectorAll('#ev-list .ev-rec').forEach(r=>{
    const isGrp=r.dataset.obj==='grp';
    const nm=r.querySelectorAll('.row>div')[1].firstElementChild.textContent;
    if(!(isGrp?(r.dataset.mem||'').split(',').includes(sevStu.name):nm===sevStu.name))return;
    if(sevF.q&&!r.dataset.n.includes(sevF.q))return;
    if(sevF.tch!=='all'&&r.dataset.tch!=='王瑶')return;
    if(sevF.type!=='all'&&r.dataset.t!==sevF.type)return;
    if(sevF.dim!=='all'&&r.dataset.dim!==sevF.dim)return;
    if((sevT.s&&r.dataset.d<sevT.s)||(sevT.e&&r.dataset.d>sevT.e))return;
    const c=r.cloneNode(true);
    c.dataset.si=sevMap.length;sevMap.push(r);
    c.querySelector('.avatar').removeAttribute('onclick'); /* 明细页内头像不再挂「进本人明细」入口 */
    if(isGrp)c.querySelectorAll('.kv')[2].insertAdjacentHTML('afterend','<div class="kv"><span class="k">点评组员</span><span class="v">'+evMems(r).join('、')+'</span></div>');
    html+=c.outerHTML;
  });
  document.getElementById('sev-list').innerHTML=html;
  document.getElementById('sev-empty').style.display=html?'none':'';
  document.getElementById('sev-fbtn').classList.toggle('act',sevF.tch!=='all'||sevF.type!=='all'||sevF.dim!=='all');
}
