/* -------- 表现排行（素质评价「表现排行」入口）：班级榜单页——
   参考稿的小红花计数在本系统对应星星；榜单按星星数（表扬 − 待改进星星合计）降序，前三名金 / 银 / 铜牌徽标；
   班级收敛为任教班级平铺单选（与表现点评同口径，排行在班级内才有可比性，不设「全部班级」）；
   时间筛选与素质评价同口径（默认本周）；筛选面板 = 点评老师 × 点评类型 × 指标维度（较点评记录筛选少「点评对象」——榜单只排学生），
   点评类型筛为表扬 / 待改进时榜单分别改按对应类型的星星数降序；计数为演示定格值：时间 / 点评老师 / 指标维度切换不重算（真实产品随条件联动重算） -------- */
/* 素质评价学生名单条目：[姓名, 女生, 表扬次数, 待改进次数]。任教三个班的定格点评次数写在这里；名单本身取演示名册（每班一份，见「演示名册」段），
   名册里其余学生在首次取用时补齐（epStus）。提前到排行榜数据之前定义：页面加载时排行榜首次渲染即会汇总演示名册 */
const EP_STUS={
 c32:[['林晓乐',0,2,0],['王梓豪',0,1,1],['吴一诺',1,2,0],['高子墨',0,1,0],['李沐宸',0,0,1],['徐若曦',1,1,0],['王一彤',1,1,0],['杨梓冉',1,0,0]],
 c31:[['陈雨桐',1,2,0],['赵梓睿',0,0,1]],
 c33:[['周欣怡',1,1,0],['刘一鸣',0,1,0],['郑浩然',0,0,1]]
};
const epFull=new Set(),rkFull=new Set(); /* 已按演示名册补齐的班级（epStus / rkStus） */
/* 榜单条目：[姓名, 女生, 表扬次数, 待改进次数, 星星合计, 表扬星星和] —— 表扬 / 待改进次数为纯次数账，
   本页不展示次数（榜单口径统一为星星），它们供学生点评明细页头部的「点评次数」使用；
   星星合计与表扬星星和为本页排序与行内明细的取数（待改进星星和 = 表扬星星和 − 星星合计），学生点评明细页头部统计同一推导 */
const RK_STUS={
 c32:[['吴一诺',1,2,0,4,4],['林晓乐',0,2,0,3,3],['高子墨',0,1,0,3,3],['徐若曦',1,1,0,2,2],['王一彤',1,1,0,1,1],['杨梓冉',1,1,0,1,1],['王梓豪',0,1,1,0,2],['李沐宸',0,0,1,-1,0]],
 c31:[['陈雨桐',1,2,0,4,4],['赵梓睿',0,0,1,-1,0]],
 c33:[['周欣怡',1,1,0,2,2],['刘一鸣',0,1,0,1,1],['郑浩然',0,0,1,-1,0]]};
const RK_SECS={tch:TEV_SECS.tch,type:TEV_SECS.type,dim:TEV_SECS.dim};
const rkF={cls:tclsCur(),tch:'all',type:'all',dim:'all'};
const rkT={preset:'week',s:TEV_PRESETS.week[1],e:TEV_PRESETS.week[2]};
/* 同分不排高下：分值相同即并列同一名次，名次按标准竞赛排名跳号（1, 1, 3）——分数一样却被排出
   先后，孩子与家长必然要问「凭什么他在我前面」，而笔画 / 学号 / 被点评时间这类次级键在教育场景里
   都没有正当性可讲。同分组内仍需一个确定的展示先后（否则每次进页面顺序抖动），取姓名拼音升序：
   中性、可复现、与学生 Tab「首字母」排序同一套，且只决定谁先显示、不体现为名次差。
   奖牌另加「分值为正」的条件：学期初全班 0 星，按名次发牌会发出一片金牌 */
/* 排行取值：全部按星星净值（表扬星星和 − 待改进星星和）；筛为表扬 / 待改进时改按对应类型的星星和——
   与页面「按星星数排名」的统一口径保持一致，不能筛到单一类型就退回按次数排（次数与星星和会因单次分值不同而背离，
   例如某生 1 次表扬却给了 2 颗星，另一生 1 次表扬只给 1 颗星，按次数并列、按星星和才分得出高下）。
   s[5] 为表扬星星和，s[4] 为净值，故待改进星星和 = s[5]−s[4]（与点评明细头部统计同一推导，见 sevStatFill） */
function rkVal(s){return rkF.type==='praise'?s[5]:rkF.type==='improve'?s[5]-s[4]:s[4]}
function rkRender(){
  const medal=rkF.type!=='improve'; /* 待改进榜不发奖牌，仅序号 */
  const list=rkStus(rkF.cls).slice().sort((a,b)=>rkVal(b)-rkVal(a)||stuColl.compare(a[0],b[0]));
  const tie={};list.forEach(s=>tie[rkVal(s)]=(tie[rkVal(s)]||0)+1); /* 各分值的同分人数 */
  let no=0,prev=null;
  document.getElementById('rk-list').innerHTML='<div class="card" style="padding:0 14px">'+list.map((s,i)=>{
    const v=rkVal(s);
    if(v!==prev){no=i+1;prev=v} /* 与上一名同分则沿用其名次，不同分才跳到当前位次 */
    const win=no<=3&&medal&&v>0; /* 奖牌：名次进前三且分值为正——学期初全班 0 星时按名次发牌会发出一片金牌 */
    return '<div class="rk-row" onclick="stuevOpen(\''+s[0]+'\',\''+rkF.cls+'\')">'
      +'<span class="rk-badge">'+(win?'<span class="rk-medal m'+no+'">'+no+'</span>':'<span class="rk-no">'+no+'</span>')+'</span>'
      +'<div class="avatar'+(s[1]?' girl':'')+'">'+s[0].slice(-1)+'</div>'
      /* 「并列」只标在发牌行：那里要解释「为什么两块金牌」；灰色序号区一堆同分（常见于 0 星）逐行标注只是噪音 */
      /* 行内明细为星星数而非点评次数：本页是星星榜单，右侧大数即星星，两个数并排却一个是次数一个是星星，
         读者只会当成其中一个算错了（吴一诺 2 次表扬得 4 星，左「表扬 2」右「4 ★」对不上）；改为星星后
         右侧 = 表扬星 − 待改进星，当场可验算。次数不在本页出现，它在点评明细页头部有专门的「点评次数」 */
      +'<div style="flex:1;min-width:0"><div style="font-size:14.5px;font-weight:700">'+s[0]+'</div><div class="rk-sub">'+(win&&tie[v]>1?'<span class="rk-tie">并列</span>':'')+'<span>表扬 '+s[5]+'</span><span>待改进 '+(s[5]-s[4])+'</span></div></div>'
      +'<b class="rk-star">'+v+' <span>★</span></b><span class="arr">›</span></div>';
  }).join('')+'</div>';
  document.getElementById('rk-fbtn').classList.toggle('act',rkF.tch!=='all'||rkF.type!=='all'||rkF.dim!=='all');
}
