 /* 初始渲染榜单 */
/* -------- 评价报告（素质评价「评价报告」入口）：选择学生 → 学生评价报告 → 下载列表，三页与家长端评价报告同构（同一报告两侧视图）。
   选择学生页按任教班级折叠分组（epStus 同源，即每班一份的演示名册）；报告页学生卡可点开半屏快捷换人；
   报告主体统计为演示定格值（与家长端评价报告同一套数，含 5 条未在点评记录列表展示的历史点评），
   切换学生 / 周期仅更新头部信息与导出文件名、不重算数据（真实产品按学生 × 周期重新生成）；
   报告内班级与全站同为「3年级-2班」格式 -------- */
const esSt={q:'',closed:{}};
/* 默认展开策略：多于 1 个班就只展开默认班、其余收起为组头，两种角色同一套，不按班级数分档。
   决定要不要折叠的是展开后的名单长度而非班级数——真实产品每班 40 余人，教师任教 2–3 个班即上百个名字、
   三列网格四十来行，与全校范围只差一个数量级（2026-10-27 起演示名册已按真实班额补满，此前每班 8–10 人掩盖了这个规模）。
   只任教 1 个班时全展开：没有可切换的对象，折叠纯属多一次点击。
   默认班级直接取表现点评那套已定版的规则（tclsCur：班主任班优先、纯任课老师取排序首位、此后记忆上次选择、
   记忆跨会话保留），只读跟随、不写回——本页是跨班浏览语义，在这里选学生不该改变那两页的当前班。
   曾一度默认全部收起，理由是「本页没有当前学生可锚定、展开哪个班都没依据」，但依据本就存在：
   老师出报告绝大多数是给自己班的孩子，展开默认班多数情况下一步到位，而全收起是无论如何都要先点一次。
   可见班级变化时（evScopeSync）班级集整个换掉，故连同搜索词一并重置重渲 */
function esInit(){
  esSt.q='';esSt.closed={};
  const cls=repClsRows();
  if(cls.length>1){const d=tclsCur(repClsAll());cls.forEach(c=>{if(c[0]!==d)esSt.closed[c[0]]=true})}
  const inp=document.querySelector('#sc-evalstu input');if(inp)inp.value='';
  esRender();
}
/* 进入本页：重置搜索与展开态、按默认班展开并把该班组头滚到列表顶部（记忆的班可能排在中段，
   展开了却在屏外等于没展开）。报告页返回本页仍走 go('sc-evalstu')，保留老师此前的搜索与展开状态——
   返回是「回到我刚才的位置」，不是重新进入 */
function esOpen(){esInit();go('sc-evalstu');esScroll()}
function esScroll(){
  const box=document.querySelector('#sc-evalstu .body'),hd=box&&box.querySelector('.es-grp:not(.closed) .es-grp-hd');
  if(box&&hd)box.scrollTop+=hd.getBoundingClientRect().top-box.getBoundingClientRect().top;
}
function esRender(){
  document.getElementById('es-list').innerHTML=repClsRows().map(([k,full])=>{
    const list=epStus(k).filter(s=>!esSt.q||s[0].includes(esSt.q));
    if(!list.length)return '';
    /* 搜索态命中的班一律展开：班级多时默认大多收起，搜到了却折着等于没搜到 */
    const closed=!esSt.q&&esSt.closed[k];
    return '<div class="es-grp'+(closed?' closed':'')+'"><div class="es-grp-hd" onclick="esToggle(\''+k+'\')"><i>▼</i>'+full+'<span style="margin-left:auto;font-size:12px;font-weight:400;color:var(--ink-3)">'+list.length+' 人</span></div>'
      +'<div class="es-grid">'+list.map(s=>'<button onclick="repPickStu(\''+s[0]+'\',\''+k+'\');go(\'sc-evalrep\')">'+s[0]+'</button>').join('')+'</div></div>';
  }).join('')||'<div style="text-align:center;color:var(--ink-3);font-size:12.5px;padding:30px 0">没有匹配的学生</div>';
}
function esSearch(v){esSt.q=v.trim();esRender()}
function esToggle(k){esSt.closed[k]=!esSt.closed[k];esRender()}
/* 报告学生：头部信息随所选学生填充（学号为演示编号，林晓乐与家长端一致） */
const REP_STU={cur:'林晓乐',cls:'c32'};
/* 报告内班级与全站同为「3年级-2班」格式（演示学号 repStuNo 仍以入学届年份开头，与家长端导出文件名一致） */
function repClsGrade(){
  const c=SCHOOL_CLS.find(x=>x.k===REP_STU.cls);
  return c?c.g+'年级-'+c.n+'班':'';
}
function repStuNo(name,cls){
  if(name==='林晓乐')return '20230216';
  const c=SCHOOL_CLS.find(x=>x.k===cls),i=epStus(cls).findIndex(s=>s[0]===name);
  return (c?(2026-c.g):2023)+String(c?c.n:1).padStart(2,'0')+String(i+1).padStart(2,'0');
}
function repPickStu(name,cls){
  REP_STU.cur=name;REP_STU.cls=cls;
  const s=epStus(cls).find(x=>x[0]===name)||['',0];
  const av=document.getElementById('rep-stu-av');
  av.classList.toggle('girl',!!s[1]);av.textContent=name.slice(-1);
  document.getElementById('rep-stu-name').textContent=name+'（'+repClsGrade()+'）';
  document.getElementById('rep-stu-no').textContent=repStuNo(name,cls);
  document.getElementById('rep-stu-sex').textContent=s[1]?'女':'男';
  repRender(); /* 亮点简评整句由数据层生成（含学生名），不再逐字段回填 */
}
/* 选择学生半屏（报告页头部学生卡的快捷换人入口）。可见范围可达全校 22 个班、真实产品每班 40+ 人，
   一次性平铺近千个名字只能靠滚，故三处收敛：
   ①姓名搜索跨班即时过滤——同一件事，整页选择学生有搜索而半屏没有，能力不该不对等；半屏本就是
     「已经在看报告、想快速换个人」的场景，比整页更需要快；
   ②名单按班级折叠分节，与整页选择学生同一形态：组头一行一个班、收起时带人数，滚动即可浏览全校。
     曾用过「顶部班级横滑 chip」，22 个班一屏只露 3 个多、要横扫六屏才到6年级，横向滚动还没有位置感；
     换成折叠后每个班占一行、20 多行纵向滚动一目了然，也不必再为多班另造一套形态；
   ③打开即展开当前学生所在班并把列表滚到该生——此前选中态渲染了却停在屏外，等于白做。
   默认展开：多于 1 个班只展开当前学生所在班、其余收起为组头（与整页选择学生同一阈值——真实产品每班
   40 余人，展开两三个班就是上百个名字），只有 1 个班时全展开。
   学生名用整页同款三列网格：此前每行 5 个 chip，三字姓名挤且不好点 */
const repSs={q:'',open:{}};
function repStuSheet(){
  repSs.q='';repSs.open={};
  const cls=repClsRows();
  /* 与整页选择学生同一阈值：多于 1 个班只展开当前学生所在班（半屏这里锚的是「正在看的学生」而非默认班），
     只有 1 个班时全展开 */
  if(cls.length>1)repSs.open[REP_STU.cls]=true;else cls.forEach(c=>repSs.open[c[0]]=true);
  repStuRender(true);
}
function repStuBody(){
  const cls=repClsRows();
  const secs=cls.map(([k,full])=>{
    /* 搜索态跨班检索、命中的班一律展开（搜到了却折着等于没搜到），无命中的班整节不出 */
    const list=epStus(k).filter(s=>!repSs.q||s[0].includes(repSs.q));
    if(!list.length)return '';
    const open=repSs.q?true:!!repSs.open[k];
    return '<div class="es-grp'+(open?'':' closed')+'" data-k="'+k+'"><div class="es-grp-hd" onclick="repSsTog(\''+k+'\')"><i>▼</i>'+full+'<span style="margin-left:auto;font-size:12px;font-weight:400;color:var(--ink-3)">'+list.length+' 人</span></div>'
      +'<div class="es-grid">'+list.map(s=>'<button class="'+(s[0]===REP_STU.cur&&k===REP_STU.cls?'on':'')+'" onclick="repSsPick(\''+s[0]+'\',\''+k+'\')">'+s[0]+'</button>').join('')+'</div></div>';
  }).join('');
  /* 固定高度而不是 max-height：半屏底边对齐，内容一少上边缘就往下窜——搜索每输入一个字结果数都在变，
     跳的不只是列表，手指正在打字的搜索框也跟着动；折叠展开 / 收起同理。代价是结果少时下方留白，
     但留白远好过跳动，也让折叠时的组头钉位真正准确（容器高度不再变） */
  return '<div class="cls-scroll" style="height:52vh">'+(secs||'<div style="height:100%;display:flex;align-items:center;justify-content:center;color:var(--ink-3);font-size:12.5px">没有匹配的学生</div>')+'</div>';
}
/* 搜索框留在不重绘的头部，输入过程中光标与焦点不丢（与多人点评半屏同款） */
function repStuRender(full){
  const body=repStuBody(),el=document.getElementById('rep-ss-body');
  /* 重绘不自动滚动：滚动位置由各调用点按语义决定（打开定位到当前学生、搜索回顶部、折叠保持原位） */
  if(!full&&el&&document.getElementById('mask').classList.contains('show')){el.innerHTML=body;return}
  sheet('<div id="repss"><h3>选择学生</h3>'+epQBox('rep-ss-q',repSs.q,'repSsSearch','输入姓名搜索')+'<div id="rep-ss-body">'+body+'</div></div>');
  repSsScroll();
}
function repSsBox(){return document.querySelector('#repss .cls-scroll')}
/* 把当前学生滚进视野（半屏只有纵向平移动画，相对位置与可视高度不受影响，可同步计算）；
   该生所在班若被折起则无选中项，退而定位到它的组头 */
function repSsScroll(){
  const box=repSsBox();if(!box)return;
  const on=box.querySelector('.es-grid button.on')||box.querySelector('.es-grp:not(.closed) .es-grp-hd');
  if(on)box.scrollTop+=on.getBoundingClientRect().top-box.getBoundingClientRect().top-box.clientHeight/2+on.offsetHeight/2;
}
function repSsSearch(v){
  repSs.q=v.trim();
  const c=document.getElementById('rep-ss-q-clr');if(c)c.style.display=repSs.q?'':'none';
  repStuRender(false);
  const box=repSsBox();if(box)box.scrollTop=0; /* 结果从第一条看起 */
}
function repSsSearchClear(){
  repSs.q='';
  const i=document.getElementById('rep-ss-q');if(i)i.value='';
  const c=document.getElementById('rep-ss-q-clr');if(c)c.style.display='none';
  repStuRender(false);
  repSsScroll(); /* 清空搜索＝回到浏览态，重新定位到当前学生 */
}
/* 展开 / 收起后把被点的组头钉回原来的视口位置：不这么做，重绘会让滚动位置跳掉——
   老师点开的是远处某个班，视线却被拉回当前学生那一段 */
function repSsTog(k){
  const box=repSsBox(),hd=box&&box.querySelector('.es-grp[data-k="'+k+'"] .es-grp-hd');
  const d=hd?hd.getBoundingClientRect().top-box.getBoundingClientRect().top:null;
  repSs.open[k]=!repSs.open[k];
  repStuRender(false);
  if(d==null)return;
  const b2=repSsBox(),h2=b2&&b2.querySelector('.es-grp[data-k="'+k+'"] .es-grp-hd');
  if(b2&&h2)b2.scrollTop+=h2.getBoundingClientRect().top-b2.getBoundingClientRect().top-d;
}
function repSsPick(n,k){repPickStu(n,k);closeSheet()}
/* 报告周期（与家长端 evr* 同构，预设复用 TEV_PRESETS，默认本学期；自定义为按月区间、走上方 mr*） */
/* -------- 报告周期自定义区间：按月选择（起止胶囊 + 年 / 月两列滚轮）--------
   报告页的预设周期（本月 / 上个月 / 本学期 / 上学期）全部按整月对齐，趋势区块也只能按月画，导出文件按月 / 学期命名，
   自定义精确到日是全页唯一的例外——一天的「报告」没有意义、却能通过校验；改为「某月到某月」后与预设、趋势窗口和命名单位一致。
   点评记录列表的自定义仍按日（dr*）：列表筛记录、按天筛是合理需求，两页语义本就不同。
   三条校验（开始不晚于结束 / 最多 6 个自然月 / 结束不晚于本月）在半屏「确定」时执行：
   6 个月上限恰等于一个学期、也等于趋势区块的回看窗口（此前「180 天」沿用的是消息保留期口径，对家长是个陌生数字）；
   结束月不晚于本月由滚轮直接约束（本年月份列只到当前月，选未来月只会得到空态）、校验仅作兜底 -------- */
const MR_NOW='2026-07';
 /* 演示「本月」 */
const MR_MAX=6;
const mrR={which:'s',s:'',e:''};
let mrTimer;
function mrInit(s,e){mrR.which='s';mrR.s=s.slice(0,7);mrR.e=e.slice(0,7)}
function mrTxt(ym){return ym?(+ym.slice(0,4))+'年'+(+ym.slice(5,7))+'月':''}
function mrMonthMax(y){return y===+MR_NOW.slice(0,4)?+MR_NOW.slice(5,7):12}
function mrBox(){
  const pill=k=>'<button class="dr-pill'+(mrR.which===k?' on':'')+'" id="mr-pill-'+k+'" onclick="mrSwitch(\''+k+'\')">'+mrTxt(mrR[k])+'</button>';
  return '<div class="dr-row">'+pill('s')+'<span class="dr-sep">至</span>'+pill('e')+'</div>'
    +'<div class="dp-wheel">'
      +'<div class="dp-col" id="mr-y" onscroll="mrScroll(this)"></div>'
      +'<div class="dp-col" id="mr-m" onscroll="mrScroll(this)"></div>'
    +'</div>'
    +'<div style="font-size:11px;color:var(--ink-3);margin-top:6px">自定义时间范围最多 6 个月</div>';
}
/* 按当前编辑端的年月定位两列（半屏 DOM 插入后调用） */
function mrFill(){
  const p=(mrR[mrR.which]||'').split('-').map(Number);
  if(!p[0])return;
  dpFill('mr-y',2024,+MR_NOW.slice(0,4),'年',p[0]);
  dpFill('mr-m',1,mrMonthMax(p[0]),'月',p[1]);
}
function mrReady(){return ['mr-y','mr-m'].every(function(i){const el=document.getElementById(i);return el&&el.children.length})}
function mrScroll(el){
  dpMark(el);
  clearTimeout(mrTimer);
  mrTimer=setTimeout(function(){mrMonths();mrCommit()},150); /* 滚动停稳后联动月份列并回写 */
}
/* 年份滚到本年时月份列只到当前月，滚回往年再放开到 12 月 */
function mrMonths(){
  if(!mrReady())return;
  const mEl=document.getElementById('mr-m'),max=mrMonthMax(dpVal('mr-y'));
  if(mEl.children.length!==max)dpFill('mr-m',1,max,'月',Math.min(dpVal('mr-m'),max));
}
function mrCommit(){
  if(!mrReady())return;
  const y=dpVal('mr-y'),m=Math.min(dpVal('mr-m'),mrMonthMax(y));
  mrR[mrR.which]=y+'-'+String(m).padStart(2,'0');
  const btn=document.getElementById('mr-pill-'+mrR.which);
  if(btn)btn.textContent=mrTxt(mrR[mrR.which]);
}
function mrSwitch(k){
  mrCommit();
  mrR.which=k;
  ['s','e'].forEach(function(x){const b=document.getElementById('mr-pill-'+x);if(b)b.classList.toggle('on',x===k)});
  mrFill();
}
function mrIdx(ym){return (+ym.slice(0,4))*12+(+ym.slice(5,7))}
/* 起止校验：不通过只提示、不写入，半屏留在自定义状态供直接改月 */
function mrCheck(){
  mrCommit();
  if(!mrR.s||!mrR.e){toast('请选择完整的起止月份');return false}
  if(mrR.s>mrR.e){toast('开始月份晚于结束月份');return false}
  if(mrIdx(mrR.e)-mrIdx(mrR.s)+1>MR_MAX){toast('最多只能选择 6 个月');return false}
  if(mrR.e>MR_NOW){toast('结束月份不能晚于本月');return false}
  return true;
}
/* 月区间落成日区间：起月首日 ～ 止月末日 */
function mrStart(){return mrR.s+'-01'}
function mrEnd(){const y=+mrR.e.slice(0,4),m=+mrR.e.slice(5,7);return mrR.e+'-'+String(new Date(y,m,0).getDate()).padStart(2,'0')}
/* 报告周期名（导出文件名用）：预设用固定名，自定义按月区间命名——同年「2026年3月–5月」、跨年「2025年11月–2026年1月」、单月「2026年3月」 */
function repPeriodName(){
  if(evR.preset!=='custom')return REP_NAME[evR.preset];
  const s=evR.s.slice(0,7),e=evR.e.slice(0,7);
  if(s===e)return mrTxt(s);
  return mrTxt(s)+'–'+(s.slice(0,4)===e.slice(0,4)?(+e.slice(5,7))+'月':mrTxt(e));
}
const evR={preset:'sem',s:TEV_PRESETS.sem[1],e:TEV_PRESETS.sem[2]};
const REP_KEYS=['month','lmonth','sem','lsem','custom'];
const REP_NAME={month:'2026年7月',lmonth:'2026年6月',sem:'2026春季学期',lsem:'2025秋季学期'};
function repdToggle(hd){const d=hd.parentNode;d.classList.toggle('open');d.querySelector('.repd-bd').style.display=d.classList.contains('open')?'':'none'}
function evrOpen(){return document.getElementById('mask').classList.contains('show')&&!!document.getElementById('evrfs')}
function evrSheet(){
  const chips='<div class="fs-chips">'+REP_KEYS.map(k=>'<button class="'+(k===evR.preset?'on':'')+'" onclick="evrPick(\''+k+'\')">'+TEV_PRESETS[k][0]+'</button>').join('')+'</div>';
  const cust=evR.preset==='custom'?mrBox():'';
  sheet('<div id="evrfs"><h3>时间筛选</h3>'
    +'<div style="display:flex;align-items:center;margin:2px 0 4px;font-size:13px"><span style="color:var(--ink-2)">当前选择日期</span><span style="margin-left:auto;font-weight:600;font-variant-numeric:tabular-nums">'+tevtFmt(evR.s)+'–'+tevtFmt(evR.e)+'</span></div>'
    +chips+cust
    +'<div style="display:flex;gap:10px;margin-top:22px"><button class="btn ghost" style="flex:1" onclick="evrReset()">重置</button><button class="btn pri" style="flex:2" onclick="evrOk()">确定</button></div></div>');
  if(evR.preset==='custom')mrFill();
}
/* 确定：自定义区间在此统一校验并写入，快捷周期点选时已生效、直接收起 */
function evrOk(){
  if(evR.preset==='custom'){
    if(!mrCheck())return;
    evR.s=mrStart();evR.e=mrEnd();evrApply();
  }
  closeSheet();
}
