/* -------- 表现点评（重构为整页流程，替代原快捷半屏 evalSheet——旧版保留为演示说明入口）：
   页面 = 姓名搜索 + 班级 / 统计周期 / 点评范围三个筛选（周期与范围仅切换标签，卡片计数为演示定格值）+ 学生 | 小组两 Tab；
   学生 Tab 网格卡（头像 + 本周 👍 表扬 / 🙁 待改进星星），点卡即对该生打开点评面板，排序可切 首字母 / 星星；
   小组 Tab 按分组方案展示小组卡 + 「新建小组」，方案经「选择分组方案」半屏切换 / 添加（重命名与删除属后续阶段）；
   底部「点评多人 / 点评多组」弹多选半屏（勾选 + 全选 + 已选计数）后进入同一点评面板。
   点评面板：关键字搜索（即时过滤，有关键字时跨维度检索并按维度分组、维度栏与二级指标 chip 隐藏，不跨表扬 / 待改进 Tab）+ 表扬 / 待改进 Tab + 我常用筛选 + 左维度栏（德智体美劳）+ 项目列表——
   单击项目即提交（单项快捷路径）；「多项点评」转多选模式（勾选 + 计数步进，底部实时合计，确认点评一次提交多项）；
   「图文点评」进整页：评语（500 字 + 常用评语插入）+ 点评项目（从我常用中选，可不选）+ 图片（演示），
   带项目发送计星星、不带项目仅发评语不计星星。提交按目标 × 项目逐条生成点评记录（小组按人数计人次、组内逐人记星），
   顶部统计与素质评价页联动，记录卡可进点评详情 -------- */
/* 素质评价名单与演示名册同源（每班一份：考勤明细、两处「代学生请假」入口看到同一批学生；真实产品由学校名册下发），首次取用后缓存：
   任教三个班保留 EP_STUS 定格条目（点评次数与报告学号顺序不变），名册里其余学生按拼音补在末尾、点评次数为 0；
   其余班级取该班名册，点评次数按班级 key 确定性派生（同一个班每次进入结果一致） */
function epStus(k){
  if(epFull.has(k))return EP_STUS[k];
  const c=SCHOOL_CLS.find(x=>x.k===k)||TEACH_CLS.find(x=>x.k===k),r=c?attcGenStudents(c.full).map(s=>[s.n,s.gen==='girl'?1:0]):[];
  let a=EP_STUS[k];
  if(a)r.filter(x=>!a.some(y=>y[0]===x[0])).sort((p,q)=>stuColl.compare(p[0],q[0])).forEach(x=>a.push([x[0],x[1],0,0]));
  else{
    let seed=0;for(let i=0;i<k.length;i++)seed=(seed*31+k.charCodeAt(i))>>>0;
    a=r.sort((p,q)=>stuColl.compare(p[0],q[0])).map((x,i)=>{const v=(seed+i*37)>>>0;return [x[0],x[1],v%4===0?2:(v%3===0?1:0),v%7===0?1:0]});
  }
  a.sort((p,q)=>stuColl.compare(p[0],q[0])); /* 手写的任教班名单也按姓名拼音排（2026-11-04）：选择学生、评价报告选学生、多选 / 图文点评、选择本组学生等半屏直接用本顺序，此前保持手写顺序（如吴一诺排在高子墨前） */
  epFull.add(k);
  return EP_STUS[k]=a;
}
/* 排行榜数据：任教班用既有定格值、名册里其余学生补 0 星；其余班由学生名单派生（每次点评按 1 星计），按星星净值降序 */
function rkStus(k){
  const e=epStus(k);
  if(RK_STUS[k]){
    if(!rkFull.has(k)){e.filter(s=>!RK_STUS[k].some(x=>x[0]===s[0])).forEach(s=>RK_STUS[k].push([s[0],s[1],s[2],s[3],s[2]-s[3],s[2]]));rkFull.add(k)}
    return RK_STUS[k];
  }
  const rows=e.map(s=>[s[0],s[1],s[2],s[3],s[2]-s[3],s[2]]);
  rows.sort((a,b)=>b[4]-a[4]);
  return RK_STUS[k]=rows;
}
/* 「素质评价 · 查看」范围内的全部学生，用于按姓名反查性别 / 班级 */
function epAllStus(){const ks=[...new Set(tclsAll().concat(epClsAll()).map(c=>c.k))];return ks.reduce(function(a,k){return a.concat(epStus(k))},[])} /* 查看与点评两个范围的并集 */
