/* 方案列表按创建正序排列（新建 push 到末尾），不做倒序也不按创建人 / 小组数 / 最近使用重排：
   本半屏通常只有 1–3 行、一屏全见，排序对「找得到」几乎没有帮助，而每新建一个就让既有项集体下移
   会让位置持续漂移——与班级列表「位置稳定的肌肉记忆优于智能排序」同一原则。
   当前方案按「方案 id」记忆并跨会话保留：方案是多人共享、他人可增删的对象，按下标记忆会在
   别人删掉靠前方案后指到另一个方案上（老师上次选的是学习组，回来变成值日组）；
   记忆值不存在（方案已被删 / 演示数据刷新重置）时回落列表首位——正序下首位通常是学期初建的主用方案。
   记忆是「每位老师 × 每个班」各一份的个人使用习惯，不是班级属性：同一个班的班主任常用「班级小组」、
   任课老师常用「值日小组」，一方的选择不该覆盖另一方。老师这一维由存储位置本身承担——真机为小程序本地存储
   （按「小程序 × 微信账号」隔离），原型为 localStorage */
function epPlanMemKey(){return 'proto-tev-plan'}
function epPlanMemAll(){try{return JSON.parse(localStorage.getItem(epPlanMemKey()))||{}}catch(e){return {}}}
function epPlanMemSet(cls,id){
  const m=epPlanMemAll();
  if(id==null)delete m[cls];else m[cls]=id;
  try{localStorage.setItem(epPlanMemKey(),JSON.stringify(m))}catch(e){}
}
function epPlanIdx(cls,list){
  const id=epPlanMemAll()[cls],i=id==null?-1:list.findIndex(p=>p.id===id);
  return i<0?0:i;
}
