/* 计次提示条：仅多人或小组点评时显示（单人点评就是 1 人次、无需说明），按实际覆盖人数明示口径；
   更换点评对象后联动刷新。多个小组存在同属多组的学生时，学生数去重、人次照和——
   与提交逻辑一致：该生按小组分别记点评和星星 */
function epPubTip(){
  const el=document.getElementById('ep-pub-tip');
  const show=epPn.isGrp||epPn.targets.length>1;
  el.style.display=show?'':'none';
  if(!show)return;
  if(epPn.isGrp){
    const all=epPn.targets.reduce((a,t)=>a.concat(epGrpMems(t)),[]);
    const uniq=new Set(all).size;
    el.textContent=all.length===uniq
      ?'本次共点评 '+uniq+' 名学生，每人分别记 1 次点评和星星'
      :'本次共点评 '+uniq+' 名学生、合计 '+all.length+' 人次，同属多个小组的学生按小组分别记点评和星星';
  }else el.textContent='本次共点评 '+epPn.targets.length+' 名学生，每人分别记 1 次点评和星星';
}
/* 更换点评对象（点「点评学生 / 点评小组」行进入）：小组点评列当前分组方案下全部小组、学生点评列当前班级全部学生，
   复用多人 / 多组点评半屏的卡片网格形态（即时搜索 + 全选 + 固定高度网格，卡片带组员名单与星星计数），
   仅保留三处语义差异——标题「更换点评对象」与按钮「确认」（确认后回填当前流程、不发起新点评）、
   打开时预勾选当前点评对象、确认时至少保留一个（对象类型不跨换——小组只换小组、学生只换学生，计次口径不变） */
let epPubSel=[],epPstQ='';
function epSelGrps(){return (epPlans[epPlanCur]?epPlans[epPlanCur].groups:[]).filter(g=>g.m.length)} /* 可选小组：空组不可点评（0 人次），不列入可选（更换点评对象 / 点评多组共用） */
/* from：'pub' 图文点评页（默认）/ 'panel' 点评面板多选模式底部的点评对象行 */
let epPubStuFrom='pub';
function epPubStuSheet(from){
  epPubStuFrom=from||'pub';
  epPstQ='';
  epPubSel=epPn.isGrp?epPn.targets.filter(n=>epSelGrps().some(g=>g.n===n)):epPn.targets.slice();
  epPubStuRender(true);
}
/* 当前搜索条件下可见的目标：全选只作用于当前搜索结果、取消也只取消这批，与多选半屏同口径 */
function epPstVisible(){
  return epPn.isGrp
    ?epSelGrps().filter(g=>!epPstQ||g.n.includes(epPstQ)).map(g=>g.n)
    :epStus(epSt.cls).filter(s=>!epPstQ||s[0].includes(epPstQ)).map(s=>s[0]);
}
function epPubStuRender(full){
  const grp=epPn.isGrp;
  const list=grp?epSelGrps().filter(g=>!epPstQ||g.n.includes(epPstQ)):epStus(epSt.cls).filter(s=>!epPstQ||s[0].includes(epPstQ));
  const cards=grp?list.map(g=>epGrpCardHtml(g,1,epPubSel,'epPubTog')).join(''):list.map(s=>epCardHtml(s,1,epPubSel,'epPubTog')).join('');
  const vis=epPstVisible();
  const allOn=vis.length>0&&vis.every(n=>epPubSel.indexOf(n)>-1);
  /* 搜索框留在不重绘的头部（光标不丢）、网格固定高度不随结果伸缩，均与多选半屏同一口径 */
  const body=(cards
    ?'<div class="ep-grid" style="grid-template-columns:repeat('+(grp?2:3)+',1fr);height:44vh;overflow-y:auto;align-content:start">'+cards+'</div>'
    :'<div class="ep-grid" style="height:44vh;display:flex;align-items:center;justify-content:center;color:var(--ink-3);font-size:12px">无匹配</div>')
   +'<div style="display:flex;align-items:center;gap:12px;margin-top:14px"><span style="display:inline-flex;align-items:center;gap:6px;font-size:13px;cursor:pointer" onclick="epPstAll()"><span style="width:18px;height:18px;border-radius:50%;border:1.5px solid #C9D3E0;display:inline-flex;align-items:center;justify-content:center;color:#fff;font-size:11px;'+(allOn?'background:var(--navy);border-color:var(--navy)':'')+'">'+(allOn?'✓':'')+'</span>全选</span><span style="font-size:13px;color:var(--ink-2)">已选：<b style="color:var(--cinnabar)">'+epPubSel.length+'</b> '+(grp?'组':'个')+'</span><button class="btn pri" style="margin-left:auto;border-radius:22px;padding:9px 30px" onclick="epPubStuOk()">确认</button></div>';
  const el=document.getElementById('ep-pst-body');
  if(!full&&el&&document.getElementById('eppst')&&document.getElementById('mask').classList.contains('show')){el.innerHTML=body;return}
  sheet('<div id="eppst">'
   +'<div style="display:flex;align-items:center;margin-bottom:10px"><span style="width:24px"></span><b style="flex:1;text-align:center;font-size:16px">更换点评对象</b><span style="width:24px;text-align:right;color:var(--ink-3);cursor:pointer" onclick="closeSheet()">✕</span></div>'
   +epQBox('ep-pst-q',epPstQ,'epPstSearch',grp?'输入组名搜索':'输入姓名搜索')
   +'<div id="ep-pst-body">'+body+'</div></div>');
}
function epPstSearch(v){
  epPstQ=v.trim();
  const c=document.getElementById('ep-pst-q-clr');if(c)c.style.display=epPstQ?'':'none';
  epPubStuRender();
}
function epPstSearchClear(){
  const i=document.getElementById('ep-pst-q');if(i)i.value='';
  epPstSearch('');if(i)i.focus();
}
function epPubTog(n){const i=epPubSel.indexOf(n);i>-1?epPubSel.splice(i,1):epPubSel.push(n);epPubStuRender()}
function epPstAll(){
  const vis=epPstVisible();
  if(vis.length&&vis.every(n=>epPubSel.indexOf(n)>-1))epPubSel=epPubSel.filter(n=>vis.indexOf(n)<0);
  else vis.forEach(n=>{if(epPubSel.indexOf(n)<0)epPubSel.push(n)});
  epPubStuRender();
}
function epPubStuOk(){
  if(!epPubSel.length){toast('至少选择一个点评对象');return}
  epPn.targets=epPubSel.slice();
  if(epPubStuFrom==='panel'){epPanelRender(true);return} /* 回点评面板：已勾选项目与多选状态都在 epPn 内，不受换人影响 */
  document.getElementById('ep-pub-stu').textContent=epPn.targets.join('、');
  epPubTip();
  closeSheet();
}
/* 添加图片：图片网格上传（演示模拟，与家长端反馈 / 请假证明材料同构）——点「＋」添加演示图片（循环取预置照片，
   真实产品为相册 / 拍照），✕ 逐张删除，最多 9 张、满后隐藏添加块，随点评同步家长 */
const EP_PUB_IMGS=['assets/photo-sample.jpg','assets/photo-cap.jpg','assets/photo-glasses.jpg','assets/photo-side.jpg','assets/photo-duo.jpg'];
let epPubImgN=0;
function epPubImgAdd(){
  if(epPubImgs.length>=9)return;
  epPubImgs.push(EP_PUB_IMGS[epPubImgN++%EP_PUB_IMGS.length]);
  epPubImgRender();
}
function epPubImgDel(i){
  epPubImgs.splice(i,1);
  epPubImgRender();
}
function epPubImgRender(){
  document.getElementById('ep-pub-imgcnt').textContent=epPubImgs.length?epPubImgs.length+'/9':'';
  document.getElementById('ep-pub-imgs').innerHTML=epPubImgs.map((u,i)=>
    '<div class="ph"><img src="'+u+'" alt="点评图片"><span class="rm" onclick="epPubImgDel('+i+')">✕</span></div>').join('')
   +(epPubImgs.length<9?'<button class="add" onclick="epPubImgAdd()">＋</button>':'');
}
/* 添加点评项（图文点评的项目选择器）：与点评面板同构——搜索 + 表扬/待改进 Tab + 我常用 + 计次说明 + 维度栏 + 二级指标 chips 分组，
   单选（radio 圈，可换选），底部取消 / 确认；确认后回填图文点评页「点评项目」行 */
const epPi={type:'good',dim:'moral',q:'',fav:0,sub:'',sel:null,score:0};
function epPubItemSheet(){
  Object.assign(epPi,{type:epPubItem?epPubItem[1]:'good',dim:epPubItem?epPubItem[0]:'moral',q:'',fav:0,sub:'',sel:epPubItem?[epPubItem[0],epPubItem[1],epPubItem[2]]:null,score:epPubItem?epPubItem[3]:0});
  epPiRender(true);
}
function epPiRender(full){
  const searching=!!epPi.q||!!epPi.fav; /* 与点评面板同口径：关键字或「我常用」均跨维度展示，维度栏与二级指标 chip 隐藏 */
  const rail=Object.entries(EP_ITEMS).map(([k,v])=>'<button class="'+(k===epPi.dim?'on':'')+'" onclick="epPi.dim=\''+k+'\';epPi.sub=\'\';epPiRender()">'+v.t+'</button>').join('');
  const rowFn=function(x){
    const dk=x.dim||epPi.dim;
    const on=epPi.sel&&epPi.sel[0]===dk&&epPi.sel[1]===epPi.type&&epPi.sel[2]===x.i;
    const sc=(epPi.type==='good'?'+':'−')+x.it[2],col=epPi.type==='good'?'var(--teal)':'#F79A2E';
    /* 选中行分值框可编辑（1–999 星，默认取项目分值） */
    return '<div class="ep-item'+(on?' on':'')+'" onclick="epPiSel(\''+dk+'\','+x.i+')"><span class="ck">'+(on?'✓':'')+'</span><span class="ic" style="background:'+epIcBg(x.it[0])+'">'+epIcSvg(x.it[0],18)+'</span><span style="font-size:13.5px;flex:1">'+x.it[1]+'</span>'
      +(on?'<span class="ep-step" onclick="event.stopPropagation()"><input type="number" class="ep-score" min="1" max="999" value="'+epPi.score+'" onchange="epPiScore(this.value)"><b style="color:#F79A2E">★</b></span>':'<b style="color:'+col+'">'+sc+'</b>')+'</div>';
  };
  const gp=searching?null:epGrouped(epPi.dim,epPi.type,'',epPi.fav,epPi.sub,rowFn);
  const chips=!searching&&gp.subs.length>1?'<div class="fs-chips" style="padding:10px 0 2px;gap:7px">'+gp.subs.map(g=>'<button class="'+(g===gp.act?'on':'')+'" style="padding:5px 13px" onclick="epPi.sub=\''+(g===gp.act?'':g)+'\';epPiRender()">'+g+'</button>').join('')+'</div>':'';
  const rows=searching?epSearched(epPi.type,epPi.q,epPi.fav,rowFn):chips+gp.html;
  const body='<div class="ep-tabs"><span class="tb'+(epPi.type==='good'?' on':'')+'" onclick="epPi.type=\'good\';epPi.sub=\'\';epPiRender()">表扬</span><span class="tb'+(epPi.type==='improve'?' on':'')+'" onclick="epPi.type=\'improve\';epPi.sub=\'\';epPiRender()">待改进</span>'
   +'<span style="display:inline-flex;align-items:center;gap:5px;font-size:13px;color:var(--ink-2);cursor:pointer" onclick="epPi.fav=epPi.fav?0:1;epPiRender()"><span style="width:17px;height:17px;border-radius:50%;border:1.5px solid #C9D3E0;display:inline-flex;align-items:center;justify-content:center;color:#fff;font-size:10px;'+(epPi.fav?'background:var(--teal);border-color:var(--teal)':'')+'">'+(epPi.fav?'✓':'')+'</span>我常用</span>'
   +'<span style="margin-left:auto;font-size:12px;color:var(--ink-3);cursor:pointer" onclick="toast(EP_TIP_TXT)">计次说明 ⓘ</span></div>'
   +'<div style="display:flex;border:1px solid var(--line);border-radius:12px;overflow:hidden;height:296px">'+(searching?'':'<div class="ep-rail">'+rail+'</div>')+'<div style="flex:1;padding:2px 12px;overflow-y:auto">'+rows+'</div></div>'
   +'<div style="display:flex;gap:10px;margin-top:14px"><button class="btn ghost" style="flex:1;border-radius:22px" onclick="closeSheet()">取消</button><button class="btn pri" style="flex:1.4;border-radius:22px" onclick="epPiOk()">确认</button></div>';
  const el=document.getElementById('ep-pi-body');
  if(!full&&el&&document.getElementById('eppi')&&document.getElementById('mask').classList.contains('show')){el.innerHTML=body;return}
  sheet('<div id="eppi">'
   +'<div style="display:flex;align-items:center;margin-bottom:8px"><span style="width:24px"></span><b style="flex:1;text-align:center;font-size:16px">添加点评项</b><span style="width:24px;text-align:right;color:var(--ink-3);cursor:pointer" onclick="closeSheet()">✕</span></div>'
   +epQBox('ep-pi-q',epPi.q,'epPiSearch')
   +'<div id="ep-pi-body">'+body+'</div></div>');
}
function epPiSearch(v){
  epPi.q=v.trim();epPi.sub='';
  const c=document.getElementById('ep-pi-q-clr');if(c)c.style.display=epPi.q?'':'none';
  epPiRender();
}
function epPiSearchClear(){
  const i=document.getElementById('ep-pi-q');if(i)i.value='';
  epPiSearch('');if(i)i.focus();
}
function epPiSel(dim,i){
  const on=epPi.sel&&epPi.sel[0]===dim&&epPi.sel[1]===epPi.type&&epPi.sel[2]===i;
  epPi.sel=on?null:[dim,epPi.type,i];
  epPi.score=on?0:EP_ITEMS[dim][epPi.type][i][2]; /* 选中即带出项目默认分值 */
  epPiRender();
}
function epPiScore(v){epPi.score=Math.max(1,Math.min(999,parseInt(v)||1));epPiRender()}
function epPiOk(){
  if(!epPi.sel){toast('请选择一个点评项目');return}
  epPubItem=[epPi.sel[0],epPi.sel[1],epPi.sel[2],epPi.score];
  document.getElementById('ep-pub-item').textContent=EP_ITEMS[epPi.sel[0]][epPi.sel[1]][epPi.sel[2]][1]+'（'+(epPi.sel[1]==='good'?'+':'−')+epPi.score+' ★）';
  closeSheet();
}
/* 常用评语：点条目正文插入评语框；每条带 编辑 / 删除 图标，底部「添加常用评语」弹表单（50 字上限）；演示数据，刷新恢复 */
/* 常用评语为教师个人语料：各人独立、互不可见也互不影响（表达习惯因人而异，共用一份会互相干扰）；
   首次使用带 10 条系统预置评语作为起点（表扬 6 条 + 待改进 4 条，覆盖德智体美劳常见场景；措辞用面向家长的陈述口吻——评语家长可见，待改进类只描述行为与下一步、不评判孩子本人，完整清单见 PRD 10.6），预置项同样可改可删；单条 50 字上限、内容必填，最多 50 条 */
const EP_PHRASE_MAX=50;
let epPhrases=['乐于助人，主动关心同学，是班级里的暖心力量。','课堂上专注投入，发言积极，愿意表达自己的见解。',
 '作业书写工整、按时完成，学习习惯保持得很好。','值日认真负责，主动整理班级环境，做事有始有终。',
 '遵守课间秩序，文明礼貌，为同学做了很好的示范。','这次活动中表现出色，比上次有明显进步，请继续保持。',
 '近期课堂上容易分心，请在家一起提醒按时休息、专注听讲。','作业未按时提交，请和孩子一起梳理一下时间安排。',
 '课间活动动作较大，已当面提醒注意安全，请在家也多叮嘱。','与同学发生了小摩擦，已引导用沟通解决，请家长配合关注。'];
function epPhraseSheet(){
  sheet('<div id="epph"><div style="display:flex;align-items:center;margin-bottom:8px"><span style="width:24px"></span><b style="flex:1;text-align:center;font-size:16px">常用评语</b><span style="width:24px;text-align:right;color:var(--ink-3);cursor:pointer" onclick="closeSheet()">✕</span></div>'
   +'<div style="max-height:48vh;overflow-y:auto">'+(epPhrases.map((p,i)=>'<div style="display:flex;align-items:center;gap:12px;background:#F7F9FB;border-radius:12px;padding:13px 14px;margin-bottom:10px"><span style="flex:1;font-size:13px;line-height:1.7;cursor:pointer" onclick="epPhrasePick('+i+')">'+p+'</span><span style="color:var(--ink-3);cursor:pointer;flex-shrink:0;display:flex" onclick="epPhraseForm('+i+')"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/><path d="m15 5 4 4"/></svg></span><span style="color:var(--ink-3);cursor:pointer;flex-shrink:0;display:flex" onclick="epPhraseDel('+i+')"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6"/><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><path d="M10 11v6"/><path d="M14 11v6"/></svg></span></div>').join('')||'<div style="text-align:center;color:var(--ink-3);font-size:12.5px;padding:24px 0">暂无常用评语，点下方按钮添加</div>')+'</div>'
   +'<div style="display:flex;gap:10px;margin-top:12px"><button class="btn ghost" style="flex:1;border-radius:24px;padding:11px" onclick="closeSheet()">取消</button><button class="btn pri" style="flex:1.4;border-radius:24px;padding:11px" onclick="epPhraseForm(-1)">添加常用评语</button></div></div>');
}
function epPhrasePick(i){
  const t=document.getElementById(epPhTarget);
  t.value=(t.value+epPhrases[i]).slice(0,500);
  document.getElementById(epPhTarget==='ted-txt'?'ted-cnt':'ep-pub-cnt').textContent=t.value.length;
  closeSheet();
}
function epPhraseForm(i){ /* i=-1 添加，否则编辑 */
  const v=i>-1?epPhrases[i]:'';
  sheet('<div><h3>'+(i>-1?'编辑':'添加')+'常用评语</h3>'
   +'<div style="background:#F5F7FA;border-radius:12px;padding:10px 12px;margin:10px 0 4px"><textarea id="ep-ph-txt" maxlength="50" rows="3" placeholder="请输入评语内容" style="width:100%;border:none;background:none;outline:none;font-size:13px;line-height:1.7;resize:none" oninput="document.getElementById(\'ep-ph-cnt\').textContent=this.value.length">'+v+'</textarea><div style="text-align:right;font-size:12px;color:var(--ink-3)"><b id="ep-ph-cnt" style="color:var(--teal)">'+v.length+'</b>/50</div></div>'
   +'<div style="display:flex;gap:10px;margin-top:14px"><button class="btn ghost" style="flex:1" onclick="epPhraseSheet()">取消</button><button class="btn pri" style="flex:1" onclick="epPhraseSave('+i+')">确认</button></div></div>');
}
function epPhraseSave(i){
  const v=document.getElementById('ep-ph-txt').value.trim();
  if(!v){toast('请输入评语内容');return}
  if(i<0&&epPhrases.length>=EP_PHRASE_MAX){toast('常用评语最多 '+EP_PHRASE_MAX+' 条');return}
  if(i>-1)epPhrases[i]=v;else epPhrases.push(v);
  toast(i>-1?'评语已更新':'评语已添加');
  epPhraseSheet();
}
function epPhraseDel(i){
  epPhrases.splice(i,1);
  toast('评语已删除');
  epPhraseSheet();
}
/* 发送校验：点评项目必填 + 评语与图片至少其一。
   不带项目的内容既不计星星也不生成点评记录，家长侧没有任何落点可看，等于发了个没人收的通知；
   而只挂项目不带评语图片，走单项点评更快，不必进本页 */
function epPubSend(){
  const txt=document.getElementById('ep-pub-txt').value.trim();
  if(!epPubItem){toast('请选择点评项目');return}
  if(!txt&&!epPubImgs.length){toast('请填写评语或添加图片');return}
  epDoSubmit([epPubItem],{note:txt,imgs:epPubImgs.slice()});
  go('sc-evalpick');
}
/* 图片全屏预览：点评记录 / 详情 / 编辑点评缩略图点击查看大图，点任意处关闭；
   同一记录多图时左右箭头循环切换、底部带页码（与家长端证明材料大图同款交互），单图不显示箭头。
   传入被点缩略图元素、取同容器全部图片为预览组，索引按元素位置（演示图片循环复用会出现重复 src，不能按 src 定位） */
let tevImgArr=[],tevImgIdx=0;
function tevImgView(el){
  const imgs=[...el.parentNode.querySelectorAll('img')];
  tevImgArr=imgs.map(im=>im.getAttribute('src'));
  tevImgIdx=Math.max(0,imgs.indexOf(el));
  tevImgShow();
  document.getElementById('img-view').classList.add('show');
}
function tevImgShow(){
  const n=tevImgArr.length;
  document.getElementById('img-view-img').src=tevImgArr[tevImgIdx];
  const cap=document.getElementById('img-view-cap');
  cap.style.display=n>1?'':'none';
  cap.textContent=(tevImgIdx+1)+' / '+n;
  document.getElementById('img-view-prev').style.display=n>1?'flex':'none';
  document.getElementById('img-view-next').style.display=n>1?'flex':'none';
}
function tevImgNav(d,ev){
  ev.stopPropagation();
  const n=tevImgArr.length;
  tevImgIdx=(tevImgIdx+d+n)%n;tevImgShow();
}
/* 小组信息（新建 / 编辑双模式）与分组方案：编辑模式由小组成员半屏「编辑小组」进入——预填图标 / 名称 / 成员，
   底部「取消」换「解散小组」；成员头像带 − 逐个移除（新建模式同样可用）；保存按模式新增或就地更新 */
const epGi={ic:'',m:[]};
let epGiEdit=-1;
 /* -1 = 新建，否则为当前分组方案下被编辑小组的索引 */
let epGiFrom='sc-evalpick';
 /* 小组信息页进入来源（表现点评 / 小组管理），保存 / 取消 / 解散后原路返回 */
function epGrpNew(){
  epGiEdit=-1;epGiFrom=curScreen==='sc-grpmgr'?'sc-grpmgr':'sc-evalpick';
  epGi.ic='';epGi.m=[];
  document.getElementById('ep-gi-name').value='';
  document.getElementById('ep-gi-nc').textContent='0';
  epGiFoot();epGiRender();go('sc-grpinfo');
}
function epGrpEdit(){
  closeSheet();
  epGiFrom=curScreen==='sc-grpmgr'?'sc-grpmgr':'sc-evalpick';
  epGiEdit=epPlans[epPlanCur].groups.findIndex(x=>x.n===epGs.n);
  const g=epPlans[epPlanCur].groups[epGiEdit];
  epGi.ic=g.ic;epGi.m=g.m.slice();
  document.getElementById('ep-gi-name').value=g.n;
  document.getElementById('ep-gi-nc').textContent=g.n.length;
  epGiFoot();epGiRender();go('sc-grpinfo');
}
function epGiCancel(){go(epGiFrom)}
function epGiFoot(){
  const b=document.getElementById('ep-gi-cancel');
  if(epGiEdit>-1){b.textContent='解散小组';b.setAttribute('onclick','epGrpDisband()')}
  else{b.textContent='取消';b.setAttribute('onclick','epGiCancel()')}
}
function epGiRender(){
  epMemSort(epGi.m); /* 新建 / 编辑小组时成员区同样按拼音排，保存后小组卡顺序与此一致 */
  const ic=document.getElementById('ep-gi-ic');
  ic.innerHTML=epGi.ic?epIcSvg(epGi.ic,44):'＋';
  ic.style.background=epGi.ic?epIcBg(epGi.ic):'#F2F4F7';
  document.getElementById('ep-gi-cnt').textContent=epGi.m.length;
  /* 必填提示只在成员为空时出：让老师在点保存被拦之前就知道，而不是撞一次墙才发现 */
  document.getElementById('ep-gi-req').style.display=epGi.m.length?'none':'';
  document.getElementById('ep-gi-mem').innerHTML=epGi.m.map(n=>'<span style="position:relative;text-align:center;width:52px"><span class="avatar'+(tevGirl(n)?' girl':'')+'" style="width:44px;height:44px;font-size:15px;display:flex;align-items:center;justify-content:center;margin:0 auto 4px">'+n.slice(-1)+'</span><span class="gi-rm" onclick="epGiRm(\''+n+'\')">−</span><span style="font-size:11px;color:var(--ink-2);display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+n+'</span></span>').join('')
   +'<span style="text-align:center;width:52px;cursor:pointer" onclick="epPickStuSheet()"><span style="width:44px;height:44px;border-radius:50%;background:#F2F4F7;display:flex;align-items:center;justify-content:center;font-size:20px;color:var(--ink-3);margin:0 auto 4px">＋</span><span style="font-size:11px;color:var(--ink-3)">添加</span></span>';
}
function epGiRm(n){epGi.m=epGi.m.filter(x=>x!==n);epGiRender()}
/* -------- 小组图标：预置图标库 + 自定义上传 --------
   上传的自定义图只作用于当前编辑的这个小组，不沉淀为该班的图标库：半屏永远只列预置图标 + 底部「自定义上传」。
   小组图标是低频的一次性配置，把每张临时上传的图攒成库，既让图标库越来越杂，也要额外背上移除、
   「库里删了但小组还在用」这类归属解释；换图时重传一次的成本，远低于维护这层库 */
function epIconSheet(){
  const ics=Object.keys(EP_GRP_ICONS);
  const cell=(inner,on)=>'<span style="width:56px;height:56px;border-radius:50%;background:'+on+';display:flex;align-items:center;justify-content:center;cursor:pointer;margin:0 auto;position:relative">'+inner+'</span>';
  sheet('<div><h3>选择图标</h3><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:14px;padding:8px 4px 2px;max-height:46vh;overflow-y:auto">'
   +ics.map(ic=>cell('<span onclick="epIconPick(\''+ic+'\')" style="display:flex">'+epIcSvg(ic,26)+'</span>',epIcBg(ic))).join('')+'</div>'
   +'<button class="btn ghost blk" style="margin-top:16px" onclick="document.getElementById(\'ep-ic-file\').click()">自定义上传</button></div>');
}
function epIconPick(ic){epGi.ic=ic;epGiRender();closeSheet()}
/* 选图校验：只收 jpg / png，单张不超过 5MB——图标最终按 240×240 存下，超大原图既传不动也没有收益 */
function epIcFile(el){
  const f=el.files&&el.files[0];el.value=''; /* 清空以便连续选同一张文件仍触发 change */
  if(!f)return;
  if(!/^image\/(png|jpeg)$/.test(f.type)){toast('仅支持 JPG 或 PNG');return}
  if(f.size>5*1024*1024){toast('图片不能超过 5MB');return}
  const r=new FileReader();
  r.onload=e=>epIcCropSheet(e.target.result);
  r.onerror=()=>toast('图片读取失败，请重试');
  r.readAsDataURL(f);
}
/* 裁剪半屏：圆形取景框固定居中，底图可拖动 + 缩放（1–3 倍，1 倍为恰好盖满取景圆）。
   确认时按当前位移与缩放换算 drawImage 参数，统一导出 240×240 —— 图标位最大只有 96px，
   存原图既浪费又让各小组清晰度不一；边界始终钳制为「图片盖满取景圆」，不会裁出白边 */
const EP_CROP_D=240;
 /* 取景框边长（CSS px），同时也是导出边长 */
const epCrop={src:'',nw:0,nh:0,s:1,dx:0,dy:0};
function epIcCropSheet(src){
  const im=new Image();
  im.onload=function(){
    Object.assign(epCrop,{src:src,nw:im.naturalWidth,nh:im.naturalHeight,s:1,dx:0,dy:0});
    sheet('<div><h3>调整图标</h3>'
     +'<div class="muted" style="margin:2px 0 12px">拖动图片调整位置，滑块缩放；圆圈内为最终显示范围</div>'
     +'<div id="ep-crop-box" style="position:relative;width:'+EP_CROP_D+'px;height:'+EP_CROP_D+'px;margin:0 auto;border-radius:50%;overflow:hidden;background:#F2F4F7;touch-action:none;cursor:grab">'
     +'<img id="ep-crop-img" src="'+src+'" alt="待裁剪图片" draggable="false" style="position:absolute;left:50%;top:50%;user-select:none;pointer-events:none">'
     +'<span style="position:absolute;inset:0;border-radius:50%;box-shadow:inset 0 0 0 2px rgba(255,255,255,.9);pointer-events:none"></span></div>'
     +'<div style="display:flex;align-items:center;gap:10px;margin:16px 2px 0"><span style="font-size:12px;color:var(--ink-3)">缩放</span>'
     +'<input type="range" id="ep-crop-s" min="1" max="3" step="0.01" value="1" style="flex:1" oninput="epCropZoom(this.value)"></div>'
     +'<div style="display:flex;gap:10px;margin-top:14px"><button class="btn ghost" style="flex:1" onclick="document.getElementById(\'ep-ic-file\').click()">重选图片</button>'
     +'<button class="btn pri" style="flex:1" onclick="epIcCropOk()">确认</button></div></div>');
    epCropLayout();
    const box=document.getElementById('ep-crop-box');
    let px=0,py=0,on=false;
    box.addEventListener('pointerdown',e=>{on=true;px=e.clientX;py=e.clientY;box.setPointerCapture(e.pointerId);box.style.cursor='grabbing'});
    box.addEventListener('pointermove',e=>{if(!on)return;epCrop.dx+=e.clientX-px;epCrop.dy+=e.clientY-py;px=e.clientX;py=e.clientY;epCropLayout()});
    box.addEventListener('pointerup',()=>{on=false;box.style.cursor='grab'});
    box.addEventListener('pointercancel',()=>{on=false;box.style.cursor='grab'});
  };
  im.onerror=()=>toast('图片读取失败，请重试');
  im.src=src;
}
function epCropZoom(v){epCrop.s=+v;epCropLayout()}
/* 计算显示尺寸并把位移钳制在「图片盖满取景圆」的范围内，再落到 img 的行内样式上 */
function epCropLayout(){
  const c=epCrop,D=EP_CROP_D,k=Math.max(D/c.nw,D/c.nh)*c.s,dw=c.nw*k,dh=c.nh*k;
  const mx=(dw-D)/2,my=(dh-D)/2;
  c.dx=Math.max(-mx,Math.min(mx,c.dx));c.dy=Math.max(-my,Math.min(my,c.dy));
  const im=document.getElementById('ep-crop-img');if(!im)return;
  im.style.width=dw+'px';im.style.height=dh+'px';
  im.style.transform='translate(-50%,-50%) translate('+c.dx+'px,'+c.dy+'px)';
}
function epIcCropOk(){
  const c=epCrop,D=EP_CROP_D,k=Math.max(D/c.nw,D/c.nh)*c.s,dw=c.nw*k,dh=c.nh*k;
  const cv=document.createElement('canvas');cv.width=D;cv.height=D;
  const im=new Image();
  im.onload=function(){
    /* 取景框左上角在缩放后图片坐标系中的位置，再除以缩放比换算回原图坐标 */
    cv.getContext('2d').drawImage(im,((dw-D)/2-c.dx)/k,((dh-D)/2-c.dy)/k,D/k,D/k,0,0,D,D);
    let url;
    try{url=cv.toDataURL('image/png')}catch(err){toast('图标处理失败，请重试');return}
    /* 只写进当前编辑的小组，不落图标库——下次要用同一张图仍需重新上传 */
    epGi.ic=url;epGiRender();closeSheet();
    toast('图标已上传');
  };
  im.src=c.src;
}
