function epGrpSave(){
  const nm=document.getElementById('ep-gi-name').value.trim();
  if(!nm){toast('请输入小组名称');return}
  if(!epGi.ic){toast('请选择小组图标');return}
  /* 小组不得为空：新建与编辑同一条口径，不设例外——只拦新建的话，老师建时加 1 人、存完再编辑移除即可绕过。
     代价是已空的小组（组员离校后自动移出，见「英语组」）必须先补人才能保存，否则只能解散；
     但空组本就该被处理掉，强制在编辑时补人是合理引导。注意这条约束的是老师的保存动作，
     不是数据里能否存在空组——系统自动移出形成的空组仍是合法状态，其空态与点评拦截照旧 */
  if(!epGi.m.length){toast('请至少添加 1 名组员');return}
  if(epPlans[epPlanCur].groups.some((x,i)=>x.n===nm&&i!==epGiEdit)){toast('已存在同名小组');return}
  if(epGiEdit>-1){ /* 编辑：就地更新，保留 👍/🙁 计数（点评记录归属小组不受改名影响，演示口径） */
    const g=epPlans[epPlanCur].groups[epGiEdit];
    g.ic=epGi.ic;g.n=nm;g.m=epMemSort(epGi.m.slice());
    toast('小组已更新');
  }else{
    epPlans[epPlanCur].groups.push({ic:epGi.ic,n:nm,m:epMemSort(epGi.m.slice()),p:0,i:0});
    toast('小组已保存');
  }
  epSt.tab='grp';epRender();grpmgrRender();go(epGiFrom);
}
/* 解散小组：确认后从当前方案移除，组员回到未分组；历史点评记录保留不受影响 */
