/* -------- 分组方案：选择 / 添加 / 重命名 / 删除 --------
   权限口径：分组方案影响全班的小组点评口径，误删他人方案代价高，故只有创建人能改，校长也不例外（2026-11-02）。无权限时该行不渲染 ✎ / 🗑（而非置灰），
   避免「看得见、点了才被拒」的挫败感 —— 与点评记录「仅本人可编辑 / 删除」同一思路 */
function epMe(){return '王瑶'} /* 当前登录账号（点评记录的「点评老师」同口径） */
function epPlanEditable(p){return p.by===epMe()} /* 仅创建人可改，校长也不例外（2026-11-02 以 V1.2.5 PRD 2.1.1.13 为准） */
