/* 方案名校验：非空 + 同班内不与其他方案重名（skip 为编辑时排除自身下标，添加时传 -1）——
   方案名是老师切换方案时唯一的识别依据，同名两个方案在半屏里无法分辨 */
function epPlanNameOk(nm,skip){
  if(!nm){toast('请输入方案名称');return false}
  if(epPlans.some((p,i)=>i!==skip&&p.n===nm)){toast('已有同名方案，请换名称');return false}
  return true;
}
