function pfPhoneStep2(){
  var code=document.getElementById('pf-code1').value.trim();
  if(!code){toast('请输入验证码');return}
  if(code.length<4){toast('验证码至少4位');return}
  pfClearTimer();
  sheet('<div class="pf-sheet-title">绑定新手机号</div>'+
    '<div style="font-size:12px;color:var(--ink-2);margin-bottom:5px">新手机号</div>'+
    '<input type="text" id="pf-new-phone" placeholder="请输入11位手机号" maxlength="11" inputmode="numeric">'+
    '<div style="font-size:12px;color:var(--ink-2);margin:14px 0 5px">验证码</div>'+
    '<div class="pf-code-row">'+
    '<input type="text" id="pf-code2" placeholder="请输入验证码" maxlength="6" inputmode="numeric">'+
    '<button class="pf-code-btn" id="pf-code2-btn" onclick="pfSendCode2()">获取验证码</button>'+
    '</div>'+
    '<div class="pf-sheet-btns">'+
    '<button class="btn ghost" onclick="closeSheet();pfClearTimer()">取消</button>'+
    '<button class="btn pri" onclick="pfPhoneConfirm()">确认换绑</button></div>');
}
function pfSendCode2(){
  var phone=document.getElementById('pf-new-phone').value.trim();
  if(!phone){toast('请先输入新手机号');return}
  if(!/^1\d{10}$/.test(phone)){toast('请输入正确的手机号');return}
  pfCountdown(document.getElementById('pf-code2-btn'));
}
function pfPhoneConfirm(){
  var phone=document.getElementById('pf-new-phone').value.trim(),code=document.getElementById('pf-code2').value.trim();
  if(!phone){toast('请输入新手机号');return}
  if(!/^1\d{10}$/.test(phone)){toast('请输入正确的手机号');return}
  if(!code){toast('请输入验证码');return}
  if(code.length<4){toast('验证码至少4位');return}
  pfClearTimer();
  var masked=phone.substring(0,3)+'****'+phone.substring(7);
  pfData.phone=masked;
  document.getElementById('pf-phone-val').textContent=masked;
  closeSheet();toast('手机号换绑成功');
}
