function tauditApprove(){
  var t=tpData[tpAuditCat].pend.find(function(x){return x.n===tpAuditName});
  if(t){
    var idx=tpData[tpAuditCat].pend.indexOf(t);tpData[tpAuditCat].pend.splice(idx,1);t.ck=false;t.time='刚刚';
    if(tpAuditCat==='reg'){ /* 注册审核：以管理员修正后的表单为准（姓名 / 性别 / 班主任班级 / 任教班级 / 称谓），两个班级字段均可为空 */
      t.n=(document.getElementById('taudit-name').value||'').trim()||t.n;
      var g=document.querySelector('#taudit-gender .fchip.on');if(g)t.gen=g.textContent==='女'?'girl':'';
      t.hr=[...TCP.ta.sets.hr].sort(dsByCls).join('、');
      t.cls=[...TCP.ta.sets.sub].sort(dsByCls).join('、');
      t.title=(document.getElementById('taudit-title-field').value||'').trim()||'老师';
      tpAuditName=t.n;
    }
  }
  toast(tpAuditCat==='reg'?'已通过，教师信息已生效':'已通过，信息已更新');
  setTimeout(function(){go('sc-tchpend');tpRender()},800);
}
function tauditReject(){
  tpRejectSheet(function(reason){
    var t=tpData[tpAuditCat].pend.find(function(x){return x.n===tpAuditName});
    if(t){var idx=tpData[tpAuditCat].pend.indexOf(t);tpData[tpAuditCat].pend.splice(idx,1);t.ck=false;t.reason=reason;t.time='刚刚';tpData[tpAuditCat].reject.push(t)}
    toast('已拒绝 '+tpAuditName);
    setTimeout(function(){go('sc-tchpend');tpRender()},800);
  });
}
function tauditRemove(){
  var t=tpData[tpAuditCat].pend.find(function(x){return x.n===tpAuditName});
  if(t){var idx=tpData[tpAuditCat].pend.indexOf(t);tpData[tpAuditCat].pend.splice(idx,1);t.ck=false}
  toast('已移除 '+tpAuditName);
  setTimeout(function(){go('sc-tchpend');tpRender()},800);
}
