const attSt={role:'teacher',period:'day',day:0,scope:'grade'};
/* 考勤明细、代学生补签的班级选择候选（2026-10-27 收敛）：与统计页同一份任教班清单 attMine，按年级分组，班主任班在前、任课班在后、同层按班号升序；
   此前两处列全校 50 个班；王老师兼任的人事专员只有教师管理权限（2026-10-27 去掉校级管理员），三个任教班即其查看 / 代补签范围 */
function attMineGrades(only){ /* only：只取这些班（代学生补签传本人持有「代补签」的班） */
  const num=c=>+(c.match(/-(\d+)班/)||[0,0])[1],hr=x=>x[1].indexOf('班主任')===0?0:1;
  const g={};attMine.filter(x=>!only||only.indexOf(x[0])>=0).sort((a,b)=>hr(a)-hr(b)||num(a[0])-num(b[0])).forEach(x=>{const k=x[0].split('-')[0];(g[k]=g[k]||[]).push(x[0])});
  return g;
}
/* 周视图数据：本周 5 个上学日累计人次，由月度（3 天）数据按 5/3 比例推算（演示） */
function attWeekData(c){return c.m.map(function(v){return Math.round(v*5/3)})}
/* 周 / 月只累计截至今天已过去的上学日（2026-11-03）：本周 = 7月6日（今天，周一）1 天、取今天数据；上周 = 6月29日–7月3日 5 天；
   本月 = 7月1–3日 + 今天共 4 天。此前本周按 7月6–10日 5 天算（提前统计了未来 4 天，675 人次）、本月只算 7月1–3日（漏了今天，405 人次），出现月比周少 */
/* 任教班的统计由考勤明细同一份名单算出（2026-11-03）：今天取 attcGenStudents 的当天记录，历史日取 attcDayStu（与考勤明细按日期生成列表同源），
   此前统计页是另外手写的一组数（如 3年级-2班 今天缺勤 8 人，点进考勤明细只有 1 人缺卡），两页对不上。按 PRD 2.7.5.1.5 日级聚合逐人计：
   全天请假 → 请假；请假之外当天没有任何到校 / 离校记录（含整天缺卡、尚未到校、部分时段请假后其余时段未到）→ 缺勤；其余为出勤，其中任一时段迟到 / 早退 / 缺卡的单列计数（部分时段请假、其余正常仍为出勤）。 */
function attDays(){
  if(attSt.period==='day')return [attSt.day===0?CAL_TODAY:new Date(2026,6,3)];
  if(attSt.period==='week')return attSt.day===0?[CAL_TODAY]:[29,30,31,32,33].map(function(x){return new Date(2026,5,x)}); /* 上周 6月29日–7月3日（7月4–5日为周末） */
  return [1,2,3].map(function(x){return new Date(2026,6,x)}).concat([CAL_TODAY]); /* 本月截至今天 */
}
var attRosterCache={};
/* 统计截止日（2026-11-04）：年级行、班级卡人数取这一天在班的学生数——日视图为所选那天，本周 / 本月为今天，上周为周期最后一天 7月5日；
   已结束的周期按周期末取，之后再有学生离校 / 转班，旧周期的人数不变。周期内离校 / 转出学生在此前上学日的人次照常计入原班 */
function attEndDay(){
  if(attSt.period==='day')return attSt.day===0?CAL_TODAY:new Date(2026,6,3);
  if(attSt.period==='week'&&attSt.day!==0)return new Date(2026,6,5);
  return CAL_TODAY;
}
function attRosterDay(cls,d){
  var isToday=calSame(d,CAL_TODAY),key=cls+'|'+dkey(d);
  if(attRosterCache[key])return attRosterCache[key];
  var r={base:0,leave:0,abs:0,late:0,early:0,miss:0};
  if(!isToday&&!attcIsSchoolDay(d))return r;
  var stus=attcGenStudents(cls,d); /* 当天在班的学生：离校 / 转出前的日子仍计入原班（2026-11-04） */
  stus.forEach(function(s0){
    var s=isToday?s0:attcDayStu(s0,d,cls);
    var ins=[s.amSt,s.pmInSt,s.eveInSt],outs=[s.amOutSt,s.pmSt,s.eveOutSt],all=ins.concat(outs).filter(Boolean);
    if(!all.length)return; /* 无记录（演示数据缺口）不计 */
    r.base++;
    if(all.every(function(x){return x==='leave'})){r.leave++;return}
    var arrived=ins.some(function(x){return x==='signed'||x==='late'})||(!isToday&&outs.some(function(x){return x==='signedout'||x==='early'}));
    if(!arrived){r.abs++;return} /* 请假之外当天无任何到校 / 离校记录即缺勤（含部分时段请假、其余时段未到，2026-11-03 新口径，PRD 2.7.5.1.5）；全天请假已在上方计请假 */
    if(ins.indexOf('late')>=0)r.late++;
    if(outs.indexOf('early')>=0)r.early++;
    if(all.indexOf('abs')>=0)r.miss++;
  });
  if(!isToday)attRosterCache[key]=r; /* 历史日定格可缓存；今天随演示操作变化，每次重算 */
  return r;
}
function attSum(cls){
  if(cls.every(function(c){return attMine.some(function(x){return x[0]===c.n})})){
    var s={base:0,leave:0,abs:0,late:0,early:0,miss:0};
    attDays().forEach(function(d){cls.forEach(function(c){var r=attRosterDay(c.n,d);for(var k in s)s[k]+=r[k]})});
    s.in=s.base-s.leave-s.abs;s.rate=s.base?(s.in/s.base*100).toFixed(1)+'%':'—';
    return s;
  }
  var thisWeek=attSt.period==='week'&&attSt.day===0;
  var days=attSt.period==='month'?4:(attSt.period==='week'?(thisWeek?1:5):1);
  var s={base:0,leave:0,abs:0,late:0,early:0,miss:0};
  cls.forEach(function(c){
    var data;
    if(attSt.period==='month')data=c.m.map(function(v,i){return v+c.d[i]}); /* 7月1–3日累计 + 今天 */
    else if(attSt.period==='week')data=thisWeek?c.d:attWeekData(c); /* 本周截至今天只有今天；上周 5 个上学日 */
    else data=c[attSt.day===0?'d':'y'];
    s.base+=c.t*days;s.leave+=data[0];s.abs+=data[1];s.late+=data[2];s.early+=data[3];s.miss+=data[4]
  });
  s.in=s.base-s.leave-s.abs;s.rate=(s.in/s.base*100).toFixed(1)+'%';
  return s;
}
