      {n:'高子墨',av:'墨',gen:'',amSt:'signed',amSub:'考勤时间 07:46',amOutSt:'signedout',amOutSub:'签退时间 11:49',pmInSt:'signed',pmInSub:'考勤时间 13:23',pmSt:'leave',pmSub:'请假提前离校 · 已通过',eveInSt:null,eveInSub:'',eveOutSt:null,eveOutSub:''}
