/* 演示名册（每班一份，见「演示名册」段 stuNamed）：该班登记学生若不在上面的基础名单里，补在末尾，再用自动生成的学生补满到真实班额
   （stuClsSize：校园签到统计的班额，如 3年级-2班 45 人；2026-10-27 起，此前 3年级-2班只有 12 + 7 = 19 人，与信息确认页、统计栏的 45 对不上）——
   考勤明细、代学生补签、两处「代学生请假」入口、学生管理与素质评价看到同一批学生、人数一致（真实产品为学籍名册）。
   补入学生按请假单记当天考勤：演示当天 7月6日 被生效中的请假单（已通过、销假待确认，已销假按缩短后的区间）全天覆盖的记为请假（如 1年级-1班 刘思远），其余记为正常到校 */
function stuClsSize(cls){for(const g of attSchool)for(const c of g.cls)if(c.n===cls)return c.t;return 44}
/* d：取哪一天在班的学生（缺省今天）。返回的仍是今天格式的记录，历史日由 attcDayStu 折成当天状态；离校 / 转班按 stuInClsOn 的生效日期过滤 / 迁入 */
/* 3年级-1班 今天（演示时刻 16:44）：该班当天有晚上第三周期，下午离校时间段至 17:30（下一周期入校开始前一分钟）；下午放学按校门通行记录显示，
   与智慧放学同一组数：班额 44 人，自动放学阈值 = 44 × 80% 向上取整 = 36 人。已到校的学生中，第 4 名（ATTC_C31_A）16:25 出校、早于放学时间 16:30，显示疑似早退；
   其余 36 人按姓名散列排开：16:30–16:37 共 34 人（连同 16:25 那位到 16:37 共 35 人），16:38 第 36 人出校达阈值即自动放学，16:41 再出 1 人，截至 16:44 到校的 37 人均已出校；当天未到校的学生仍为待签退。
   attcC31Demo 为演示说明里的两种后续：back = 16:50 再次被识别（改正常签退，同一学生同段只计一次出校），close = 17:30 下午离校时间段结束（疑似早退定案为早退，仍无记录的记缺卡） */
var attcC31Demo={back:false,close:false},ATTC_C31_A='';
function attcC31Today(list){
  var dm=attcC31Demo||{},el=[]; /* 页面加载早期（名册自检）就会生成名单，那时演示开关尚未赋值 */
  list.forEach(function(s){
    if(!s.pmSt)return;
    if(!s.eveInSt){s.eveInSt='nosign';s.eveInSub='待签到 · 上学时段';s.eveOutSt='nosignout';s.eveOutSub='待签退 · 放学时段'} /* 班次按班级配置：全班都有晚上周期 */
    if(s.pmSt==='nosignout'&&(s.pmInSt==='signed'||s.pmInSt==='late'))el.push(s);
  });
  var A=el[3];
  if(A){
    ATTC_C31_A=A.n;
    if(dm.back){A.pmSt='signedout';A.pmSub='签退时间 16:50'}
    else{A.pmSt='suspect';A.pmSub='签退时间 16:25 · 17:30 后确认'}
  }
  var out=el.filter(function(s){return s!==A}).sort(function(x,y){return stuHash(x.n)-stuHash(y.n)}),L=out.length;
  out.forEach(function(s,r){s.pmSt='signedout';s.pmSub='签退时间 '+stuHM(r<L-2?990+Math.floor(r*8/(L-2)):r===L-2?998:1001)});
  if(dm.close)list.forEach(function(s){
    if(s.pmSt==='suspect'){s.pmSt='early';s.pmSub=s.pmSub.replace(' · 17:30 后确认','（早退）')}
    else if(s.pmSt==='nosignout'){s.pmSt='abs';s.pmSub='缺卡 · 截至 17:30 未签退'}
  });
}
