function attcC31Set(k){
  if(k==='reset')attcC31Demo={back:false,close:false};else attcC31Demo[k]=true;
  attcStudents=[];if(asClsName==='3年级-1班')asInitStudents();
  attcGo('3年级-1班');attcSetDate('2026-07-06');attcShowPm();
  demoToast({back:'演示：'+ATTC_C31_A+' 16:50 再次被校门识别，下午放学改为正常签退（签退时间 16:50）',
    close:'演示：时间来到 17:30，3年级-1班 下午离校时间段结束——疑似早退定案为早退，仍无离校记录的记缺卡',
    reset:'演示：已回到 16:44'}[k]);
}
function attcGenStudents(clsName,d){
  const s=attcGenBase(clsName),day=[plAbs('7月6日 08:00'),plAbs('7月6日 '+String(Math.floor(lvsDayEnd(clsName)/60)).padStart(2,'0')+':'+String(lvsDayEnd(clsName)%60).padStart(2,'0'))] /* 全天 = 08:00 至该班当天最后放学时间 */,dk=dkey(d||STU_TODAY);
  const hm=t=>(''+Math.floor(t/60)).padStart(2,'0')+':'+(''+t%60).padStart(2,'0');
  /* 转入学生排在补满学生之后：补满人数只按本班原有名单算，转入后班额 +1，其余学生的当天记录不变（此前转入会顶掉一名补满学生，班额不变） */
  const movedIn=Object.entries(STU_MOVED).filter(([n,m])=>m.to===clsName&&dk>=m.d).map(([n,m])=>[n,m.girl]);
  const named=(stuNamed()[clsName]||[]).filter(x=>!s.some(y=>y.n===x[0]));
  const fill=stuFillNames(clsName,64).filter(x=>!s.some(y=>y.n===x[0])&&!named.some(y=>y[0]===x[0])).slice(0,Math.max(0,stuClsSize(clsName)-s.length-named.length));
  named.concat(fill,movedIn.filter(x=>!s.some(y=>y.n===x[0])&&!named.some(y=>y[0]===x[0]))).forEach((x,k)=>{
    const lv=lvRecs().find(r=>r.name===x[0]&&r.cls===clsName&&['已通过','销假待确认','已销假'].includes(r.st)&&plAbs(r.s)<=day[0]&&plAbs(lvEffEnd(r))>=day[1]); /* 生效中的单：已销假按缩短后的区间 */
    s.push(Object.assign({n:x[0],av:x[0].slice(-1),gen:x[1]?'girl':''},lv?
     {amSt:'leave',amSub:lv.ty+' · 7月6日全天 · '+lv.st,amOutSt:null,amOutSub:'',pmInSt:null,pmInSub:'',pmSt:null,pmSub:''}:
     {amSt:'signed',amSub:'考勤时间 '+hm(451+k*7%29),amOutSt:'signedout',amOutSub:'签退时间 '+hm(702+k*5%13),
      pmInSt:'signed',pmInSub:'考勤时间 '+hm(785+k*5%20),pmSt:'nosignout',pmSub:'待签退 · 放学时段'},
     {eveInSt:null,eveInSub:'',eveOutSt:null,eveOutSub:''}));
  });
  /* 按姓名拼音排（stuColl）：考勤明细、代学生补签与其余名单同一顺序（2026-11-03，此前为演示数据写入顺序） */
  const out=s.filter(x=>stuInClsOn(x.n,clsName,d)).sort((p,q)=>stuColl.compare(p.n,q.n));
  if(clsName==='3年级-1班'&&dk===dkey(STU_TODAY))attcC31Today(out);
  return out;
}
var attcStudents=attcGenStudents(attcClsName);
function attcRow(s,st,sub,dim){
  if(!st)return '';
  var m=attcStMap[st];
  if(!m)return '';
  /* 状态标签只表状态、不带跳转箭头；整行都可点进签到详情（含待签到 / 待签退） */
  return '<div class="stu clickable" data-name="'+s.n+'" data-st="'+st+'" data-dim="'+dim+'"><div class="avatar'+(s.gen?' '+s.gen:'')+'">'+s.av+'</div>'+
    '<div><div class="nm">'+s.n+'</div><div class="sub">'+sub+'</div></div>'+
    '<div class="st-grp"><span class="chip '+m.chip+'">'+m.lab+'</span></div></div>';
}
/* 时段内的上学/放学分组 */
function attcSubGroup(label,action,signed,total,color,rows,dim,collapsed){
  return '<div class="attc-grp'+(collapsed?' collapsed':'')+'">'+
    '<div class="attc-grp-hd" onclick="attcToggle(this)">'+
    '<span class="bar" style="background:'+color+'"></span>'+
    '<span class="lab">'+label+'</span>'+
    '<span class="cnt">'+action+': '+signed+'/'+total+'</span>'+
    '<span class="arr">▼</span></div>'+
    '<div class="attc-grp-bd"><div style="padding:0 4px">'+rows+'</div></div></div>';
}
/* 时段容器（上午/下午/晚上），内部包含上学+放学两个分组 */
function attcPeriod(periodLabel,subGroups){
  return '<div style="margin-top:12px">'+
    '<div style="display:flex;align-items:center;gap:8px;padding:8px 2px 6px">'+
    '<span style="width:3px;height:14px;border-radius:2px;background:var(--navy)"></span>'+
    '<span style="font-size:14px;font-weight:700;color:var(--ink)">'+periodLabel+'</span></div>'+
    subGroups.join('')+'</div>';
}
function attcToggle(el){el.parentElement.classList.toggle('collapsed')}
function renderAttc(){
  plProxySync();
  const clsTxt=document.getElementById('attc-cls-txt');
  if(clsTxt)clsTxt.textContent=attcClsName;
  /* 班级变更时重新生成该班学生数据 */
  if(!attcStudents.length||attcStudents._cls!==attcClsName){
    attcStudents=attcGenStudents(attcClsName);
    attcStudents._cls=attcClsName;
  }
  const f=ddVal('attc-st');
  /* 2026-10-28：列表按筛选栏所选日期生成。今天用 attcStudents 的实时记录；历史上学日逐人折自签到详情页同一套定格记录（stuDaysGen / 林晓乐 linListRec），只有上午上学、下午放学两栏；周末为非上学日空态 */
  const selD=attcSelDate(),isToday=calSame(selD,CAL_TODAY);dpLabelSync('attc');
  const note=document.getElementById('attc-note');
  if(note)note.textContent=isToday?'数据来自校门无感考勤，更新约延迟 1–5 分钟':'数据来自校门无感考勤';
  if(!isToday&&!attcIsSchoolDay(selD)){
    document.getElementById('attc-main').innerHTML='<div class="card" style="text-align:center;padding:36px 0 34px;margin-top:12px"><div style="width:52px;height:52px;border-radius:16px;background:#EEF0F4;display:flex;align-items:center;justify-content:center;margin:0 auto 12px;color:#A6AEBD"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="5.5" width="16" height="15" rx="2.5"/><path d="M8 3.5v3.5M16 3.5v3.5M4 10.5h16"/></svg></div><div style="font-size:13.5px;font-weight:600;color:var(--ink-2)">'+(selD.getMonth()+1)+'月'+selD.getDate()+'日 '+CAL_WD[selD.getDay()]+' · 非上学日</div><div class="muted" style="margin-top:5px;font-size:12px">当日无考勤数据</div></div>';
    return;
  }
  const dayStus=isToday?attcStudents:attcGenStudents(attcClsName,selD).map(function(s){return attcDayStu(s,selD,attcClsName)}); /* 历史日列当天在班的学生：之后离校 / 转出的照常列出，之后转入的不列（2026-11-04） */
  const amFilters=['all','nosign','signed','late','abs','leave'];
  const pmFilters=['all','nosignout','signedout','early','abs','leave'];
  const showIn=amFilters.indexOf(f)>-1;  /* 上学类筛选 */
  const showOut=pmFilters.indexOf(f)>-1; /* 放学类筛选 */
  let h='';
  /* 6个时间点定义：[字段st, 字段sub, label, action, color, dim, 是否上学类] */
  var timePoints=[
    {stKey:'amSt',subKey:'amSub',label:'上学',action:'签到',color:'var(--teal)',dim:'am',isIn:true},
    {stKey:'amOutSt',subKey:'amOutSub',label:'放学',action:'签退',color:'#E8941A',dim:'amOut',isIn:false},
    {stKey:'pmInSt',subKey:'pmInSub',label:'上学',action:'签到',color:'var(--teal)',dim:'pmIn',isIn:true},
    {stKey:'pmSt',subKey:'pmSub',label:'放学',action:'签退',color:'#E8941A',dim:'pm',isIn:false},
    {stKey:'eveInSt',subKey:'eveInSub',label:'上学',action:'签到',color:'var(--teal)',dim:'eveIn',isIn:true},
    {stKey:'eveOutSt',subKey:'eveOutSub',label:'放学',action:'签退',color:'#E8941A',dim:'eveOut',isIn:false}
  ];
  var periods=[
    {label:'上午',tps:[0,1]},
    {label:'下午',tps:[2,3]},
    {label:'晚上',tps:[4,5]}
  ];
  periods.forEach(function(p){
    var subGroups=[];
    var hasAny=false;
    p.tps.forEach(function(tpIdx){
      var tp=timePoints[tpIdx];
      /* 筛选时不显示不相关的时间点 */
      if(f!=='all'){
        if(tp.isIn&&!showIn)return;
        if(!tp.isIn&&!showOut)return;
      }
      var list=dayStus.filter(function(s){return s[tp.stKey]&&attcStIs(s[tp.stKey],f)})
        .sort(function(x,y){return ATTC_ST_ORD[x[tp.stKey]]-ATTC_ST_ORD[y[tp.stKey]]}); /* 稳定排序：先按状态，同状态内保持名册的姓名拼音顺序 */
      if(!list.length)return;
      hasAny=true;
      var signed=0;
      list.forEach(function(s){
        if(tp.isIn&&(s[tp.stKey]==='signed'||s[tp.stKey]==='late'))signed++;
        if(!tp.isIn&&['signedout','early','suspect'].indexOf(s[tp.stKey])>-1)signed++; /* 签退计数 = 已有离校记录的人数，含早退 / 疑似早退 */
      });
      var rows=list.map(function(s){return attcRow(s,s[tp.stKey],s[tp.subKey],tp.dim)}).join('');
      /* 上午上学默认展开，其余默认折叠 */
      var collapsed=!(tpIdx===0);
      subGroups.push(attcSubGroup(tp.label,tp.action,signed,list.length,tp.color,rows,tp.dim,collapsed));
    });
    if(hasAny){
      h+=attcPeriod(p.label,subGroups);
    }
  });
  document.getElementById('attc-main').innerHTML=h;
  document.querySelectorAll('#attc-main .stu').forEach(function(row){
    row.addEventListener('click',function(e){
      if(e.target.closest('button'))return;
      /* 任意状态的学生都进签到详情，按该生当天记录渲染并定位筛选栏所选日期；待签到的学生可能已到班但忘带校徽，老师同样要点进去看 */
      attcStuOpen(this.dataset.name);
    });
  });
}
var attcSignName='周雨桐';
/* ======== 日期筛选：考勤明细（attc）与代学生补签（as）共用一套「‹ 日期 ›」胶囊 + 半屏月历（2026-10-28，替换原生 input[type=date]：小程序里该控件是系统滚轮、桌面是浏览器面板，与整套风格不符且带清除 / 真实今天） ======== */
var attcDate='2026-07-06',asDate='2026-07-06';
function dstrOf(d){return (d.getMonth()+1)+'月'+d.getDate()+'日'}
function dkey(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function dparse(v){var m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(v||'');return m?new Date(+m[1],+m[2]-1,+m[3]):new Date(CAL_TODAY)}
/* 筛选栏所选日期 */
function attcSelDate(){return dparse(attcDate)}
function asSelDate(){return dparse(asDate)}
/* 演示数据范围内的上学日：2026年6月1日–7月6日 的工作日 */
function attcIsSchoolDay(d){return d>=new Date(2026,5,1)&&d<=CAL_TODAY&&d.getDay()!==0&&d.getDay()!==6}
/* 日期胶囊文案：今天带「今天」前缀，其余为「M月D日 周X」 */
function dateLabel(d){return (calSame(d,CAL_TODAY)?'今天 ':'')+dstrOf(d)+(calSame(d,CAL_TODAY)?'':' '+CAL_WD[d.getDay()])}
const DP_CTX={attc:{get:function(){return attcDate},set:function(v){attcSetDate(v)},lab:'attc-date-lab'},as:{get:function(){return asDate},set:function(v){asSetDate(v)},lab:'as-date-lab'}};
function dpLabelSync(ctx){var c=DP_CTX[ctx],el=document.getElementById(c.lab);if(el)el.textContent=dateLabel(dparse(c.get()))}
/* ‹ › 切上一 / 下一天（2026-11-03 起不跳过周末：周末也可能上课，上学日以校历与班次为准）；到今天 / 演示范围起点为止 */
function dpStep(ctx,dir){
  var d=dparse(DP_CTX[ctx].get());
  d.setDate(d.getDate()+dir);if(d>CAL_TODAY){toast('已是今天');return}if(d<new Date(2026,5,1)){demoToast('演示：仅提供 2026年6月1日起 的考勤数据');return}
  DP_CTX[ctx].set(dkey(d));
}
/* 半屏月历：今天及以前可选（含周末，2026-11-03 去掉周末置灰），未来 / 范围外置灰；‹ › 切月（仅 2026年6月–7月） */
var dp={ctx:'attc',y:2026,m:6};
function dpOpen(ctx){
  dp.ctx=ctx;var d=dparse(DP_CTX[ctx].get());dp.y=d.getFullYear();dp.m=d.getMonth();
  sheet('<h3>选择日期</h3>'+
   '<div class="cal-hd" style="margin:2px 0 0"><b id="dp-title"></b><button class="cnav prev" onclick="dpNav(-1)">‹</button><button class="cnav" onclick="dpNav(1)">›</button></div>'+
   '<div class="cal-wk"><span>日</span><span>一</span><span>二</span><span>三</span><span>四</span><span>五</span><span>六</span></div>'+
   '<div class="cal-grid" id="dp-grid"></div>'+
   '<div class="dp-ft"><span>未来日期不可选</span><button onclick="dpPick(2026,6,6)">回到今天</button></div>');
  dpRender();
}
function dpRender(){
  var sel=dparse(DP_CTX[dp.ctx].get()),start=calWS(new Date(dp.y,dp.m,1)),days=(calWS(new Date(dp.y,dp.m+1,0))-start)/864e5+7,h='';
  document.getElementById('dp-title').textContent=dp.y+'年'+(dp.m+1)+'月';
  for(var i=0;i<days;i++){
    var d=new Date(start);d.setDate(start.getDate()+i);
    var dim=d.getMonth()!==dp.m,off=d>CAL_TODAY||d<new Date(2026,5,1);
    h+='<button class="cd'+(dim?' dim':'')+(off?' off':'')+(calSame(d,sel)?' sel':'')+(calSame(d,CAL_TODAY)?' tdy':'')+'" onclick="dpPick('+d.getFullYear()+','+d.getMonth()+','+d.getDate()+')"><span>'+d.getDate()+'</span></button>';
  }
  document.getElementById('dp-grid').innerHTML=h;
}
function dpNav(dir){
  var m=dp.m+dir;
  if(m>6){toast('已是本月');return}
  if(m<5){demoToast('演示：仅提供 2026年6月–7月 的考勤数据');return}
  dp.m=m;dpRender();
}
function dpPick(y,m,d){closeSheet();DP_CTX[dp.ctx].set(dkey(new Date(y,m,d)))}
/* 历史上学日：把签到详情页同一套定格记录折成考勤明细行（上学 / 放学两栏，午间与晚自习历史记录不保留） */
function attcDayStu(s,d,cls){
  var o={n:s.n,av:s.av,gen:s.gen,amSt:null,amSub:'',amOutSt:null,amOutSub:'',pmInSt:null,pmInSub:'',pmSt:null,pmSub:'',eveInSt:null,eveInSub:'',eveOutSt:null,eveOutSub:''};
  var dstr=(d.getMonth()+1)+'月'+d.getDate()+'日';
  if(s.n===LIN_NAME&&(cls||attcClsName)===LIN_CLS){var l=linListRec(d);o.amSt=l.amSt;o.amSub=l.amSub;o.pmSt=l.pmSt;o.pmSub=l.pmSub;return o}
  var r=stuDaysGen(s)[calKey(d)];
  if(!r)return o;
  if(r.t==='leave'){o.amSt=o.pmSt='leave';o.amSub=o.pmSub='请假 · '+dstr+' · 已通过';return o}
  if(r.t==='absent'){o.amSt='abs';o.amSub='缺卡 · 截至 10:59 未签到';o.pmSt='abs';o.pmSub='缺卡 · 截至 '+attcPmEnd(cls)+' 未签退';return o}
  o.amSt=r.late?'late':'signed';o.amSub='考勤时间 '+r.in;
  if(r.miss){o.pmSt='abs';o.pmSub='缺卡 · 截至 '+attcPmEnd(cls)+' 未签退'}
  else{o.pmSt=r.early?'early':'signedout';o.pmSub='签退时间 '+r.out}
  return o;
}
function attcSetDate(v){attcDate=v;dpLabelSync('attc');renderAttc()}
function asSetDate(v){asDate=v;dpLabelSync('as');asRender();if(asPeriod&&asPoint)asFormReset()} /* 今天与历史日的时间上限不同，切日期后时间与状态回到默认 */
/* 班级选择：参照教师注册页任教班级选择组件（左年级栏+右班级chips），单选 */
var attcCurG='3年级';
function attcClsSheet(){
  sheet('<h3>选择班级</h3>'+
   '<div style="display:flex;border:1px solid var(--line);border-radius:12px;overflow:hidden;height:300px;flex-shrink:0">'+
     '<div id="attc-grades" style="width:88px;background:#EFF3F9;overflow-y:auto;flex-shrink:0"></div>'+
     '<div style="flex:1;padding:10px 10px 6px;overflow-y:auto"><div class="fchips" id="attc-cls-list" style="gap:7px"></div></div>'+
   '</div>');
  attcClsRender();
}
function attcClsRender(){
  var gEl=document.getElementById('attc-grades');
  if(!gEl)return;
  var mine=attMineGrades();if(!mine[attcCurG])attcCurG=Object.keys(mine)[0];
  gEl.innerHTML=Object.keys(mine).map(function(g){
    return '<button onclick="attcCurG=\''+g+'\';attcClsRender()" style="display:block;width:100%;text-align:left;padding:11px 12px;font-size:12.5px;'+(g===attcCurG?'background:#fff;color:var(--navy);font-weight:600;border-left:3px solid var(--navy);':'color:var(--ink-2);border-left:3px solid transparent;')+'">'+g+'</button>';
  }).join('');
  var h='';
  mine[attcCurG].forEach(function(k){
    var isCur=attcClsName===k;
    h+='<button class="fchip'+(isCur?' on':'')+'" onclick="attcClsPick(\''+k+'\')">'+k+(isCur?' ✓':'')+'</button>';
  });
  document.getElementById('attc-cls-list').innerHTML=h;
}
function attcClsPick(k){
  attcClsName=k;
  closeSheet();
  renderAttc();
}
function attcFilterChange(){renderAttc()}
/* -------- 状态筛选下拉面板（考勤明细 / 代学生补签 / 信息确认 / 办理记录）：从筛选栏下沿展开，选中项蓝字打勾，点遮罩或面板外任意位置收起 -------- */
var DD_OPTS={
  'attc-st':{opts:[['all','全部'],['nosign','待签到'],['signed','正常签到'],['late','迟到'],['nosignout','待签退'],['signedout','正常签退'],['early','早退'],['abs','缺卡'],['leave','请假']],on:function(){attcFilterChange()}},
  'as-st-filter':{opts:[['all','全部'],['nosign','待签到'],['signed','正常签到'],['late','迟到'],['abs','缺卡'],['leave','请假']],on:function(){asRender()}}, /* 选项随补签时段的上学 / 放学切换，见 asUpdateForm */
  'ap-filter':{opts:[['all','全部'],['no','未提交'],['wait','待确认'],['ok','已确认']],on:function(v){colFilterSel(v)}},
  'br-filter':{opts:[['all','全部'],['wait','待确认'],['ok','已确认']],on:function(v){brFilter(v)}}
};
var ddCur=null;
function ddVal(id){var b=document.getElementById(id);return (b&&b.dataset.v)||'all'}
function ddSet(id,v){
  var b=document.getElementById(id);if(!b)return;
  var opts=DD_OPTS[id].opts,o=opts.filter(function(x){return x[0]===v})[0]||opts[0];
  b.dataset.v=o[0];b.querySelector('span').textContent=o[1];
}
function ddOpen(id){
  if(ddCur){var same=ddCur===id;ddClose();if(same)return}
  var btn=document.getElementById(id),phone=btn.closest('.phone'),bar=btn.parentElement;
  /* 手机壳可能被缩放展示，按实际缩放比换算面板位置 */
  var pr=phone.getBoundingClientRect(),k=(pr.height/phone.offsetHeight)||1;
  var top=Math.round((bar.getBoundingClientRect().bottom-pr.top)/k)+6,v=ddVal(id);
  var mask=document.createElement('div');mask.className='dd-mask';mask.id='dd-mask';mask.style.top=top+'px';mask.onclick=ddClose;
  var p=document.createElement('div');p.className='dd-panel';p.id='dd-panel';p.style.top=top+'px';
  p.innerHTML=DD_OPTS[id].opts.map(function(o){
    return '<button class="dd-opt'+(o[0]===v?' on':'')+'" onclick="ddPick(\''+id+'\',\''+o[0]+'\')"><span>'+o[1]+'</span>'+(o[0]===v?'<i>✓</i>':'')+'</button>';
  }).join('');
  phone.appendChild(mask);phone.appendChild(p);
  btn.classList.add('open');ddCur=id;
  requestAnimationFrame(function(){mask.classList.add('show');p.classList.add('show')});
}
function ddClose(){
  if(!ddCur)return;
  var b=document.getElementById(ddCur);if(b)b.classList.remove('open');
  ['dd-mask','dd-panel'].forEach(function(i){var e=document.getElementById(i);if(e)e.remove()});
  ddCur=null;
}
