  if(s.pmSt==='signedout'||s.pmSt==='early'||s.pmSt==='suspect'){r.out=stuT(s.pmSub);if(s.pmSt==='early')r.early=990-stuMin(r.out);if(s.pmSt==='suspect')r.suspect=1} /* 疑似早退：暂定，不计早退、当天不标异常 */
  else if(s.pmSt==='abs')r.miss=1;else if(s.pmSt==='leave')r.pmLeave=1;else r.pend=true;
  if(s.amOutSt==='early')r.early=r.early||690-stuMin(stuT(s.amOutSub)); /* 上午放学早退：按上午放学时间 11:30 计分钟 */
  if(r.late||r.early||r.miss)r.t='abn';
