      if(i===er){r.t='abn';r.early=5+(h+i)%25;r.out=stuHM(990-r.early)} /* 离校 16:05–16:25：早于 16:00 离校落在下午入校时段，不算离校记录 */
      if(i===ms){r.t='abn';r.miss=1;r.out=null}
