/* -------- 林晓乐（3年级-2班）：6月1日–7月4日 的历史记录与家长端 parent.js 同一套演示日期（2026-10-27 对齐，两端并排演示时圆点、按日视图与统计数字一致）——
   数据常量与按日视图逐段移植自家长端 genDayHtml（去掉毕业归档与六次打卡分支），其余学生仍用下方按姓名生成的定格记录；今天（7月6日）两端各按本端当天记录 -------- */
const LIN_NAME='林晓乐',LIN_CLS='3年级-2班';
function stuIsLin(){return !!stuCur&&stuCur.n===LIN_NAME&&stuCur.cls===LIN_CLS}
/* 已知到离校时间；[入,出,是否迟到]（7-3 为家长端「上一上学日」静态视图的时间） */
const CAL_KNOWN={'7-3':['07:39','16:35',0],'7-2':['08:21','16:30',1],'7-1':['07:44','16:33',0],'6-30':['07:41','16:36',0],'6-11':['07:52','16:31',0],'6-5':['07:47','16:32',0]};
