   +stuNode('in','到校 --:-- <span class="tm">（上学时间 08:00）</span>'+chipOf('red','缺卡'),'未采集到到校通行记录',null,true)
   +(today?stuNode('out','离校 · 待记录 <span class="tm">（放学时间 16:30）</span>','放学出校门后自动生成，并推送家长离校通知',null,true)
     :stuNode('out','离校 --:-- <span class="tm">（放学时间 16:30）</span>'+chipOf('red','缺卡'),'未采集到离校通行记录',null,true))+'</div></div>';
