/* 学生详情：离校日期默认今天；滚轮与离校半屏共用 sheet，取消保留原值。 */
var sdLeaveDate='';
function sdLeaveSheet(keep){
  if(!keep){
    sdLeaveDate=dkey(CAL_TODAY); /* 默认演示「今天」7月6日（2026-11-04；此前取电脑当天日期，晚于全部演示考勤数据，离校后考勤名单看不出变化） */
  }
  sheet('<h3>离校</h3>'+
    '<div class="cx-grp"><div class="cx-row" onclick="sdLeavePick()"><span>离校日期</span><b>'+sdLeaveDate+'</b><i class="arr">›</i></div></div>'+
    '<div class="row" style="gap:10px;margin-top:14px">'+
      '<button class="btn ghost" style="flex:1" onclick="closeSheet()">取消</button>'+
      '<button class="btn pri" style="flex:1" onclick="sdLeaveConfirm()">确认离校</button>'+
    '</div>');
}
function sdLeavePick(){
  var p=sdLeaveDate.split('-').map(Number),years=[],y=new Date().getFullYear();
  // 办理日期以当前年为中心提供前后十年，不复用出生日期的固定年份范围。
  for(var n=Math.min(y-10,p[0]);n<=Math.max(y+10,p[0]);n++)years.push(n);
  pickerSheet('选择离校日期',[
    {items:years.map(function(v){return v+'年'}),idx:years.indexOf(p[0])},
    {items:Array.from({length:12},function(_,i){return (i+1)+'月'}),idx:p[1]-1},
    {items:pkDays(p[0],p[1]),idx:p[2]-1}
  ],function(s){
    var year=years[s[0]],month=s[1]+1,day=Math.min(s[2]+1,new Date(year,month,0).getDate());
    sdLeaveDate=year+'-'+String(month).padStart(2,'0')+'-'+String(day).padStart(2,'0');
    sdLeaveSheet(true);
  },function(i){
    if(i<2)pkSetItems(2,pkDays(years[pkIdx(0)],pkIdx(1)+1));
  },function(){sdLeaveSheet(true)});
}
function sdLeaveConfirm(){
  if(!sdLeaveDate){toast('请选择离校日期');return}
  closeSheet();
  var name=window.sdCurName;
  if(!smGone(name,'离校',sdLeaveDate))return;
  toast('已办理离校：'+name+' · '+sdLeaveDate);
  setTimeout(function(){go('sc-stumgr')},800);
}
