/* -------- 信息确认页：搜索+下拉联动 / 班级折叠 / 年级班级筛选 -------- */
var colState={q:'',f:'all'};
/* 信息确认页空态（2026-10-27）：筛选 / 搜索无命中——隐藏没有命中行的班级卡与年级卡，列表区显示「暂无符合条件的学生」。
   持有「查看」但范围内没有班级时首页不显示宫格与活动横幅（meCanSee），本页不另设空态 */
function apEmptySet(mode){
  var e=document.getElementById('ap-empty');if(!e)return;
  e.style.display=mode?'':'none';
}
function colApply(){
  var active=colState.q||colState.f!=='all';
  document.querySelectorAll('.col-list .stu').forEach(r=>{
    var okF=colState.f==='all'||r.dataset.cf===colState.f;
    var okQ=!colState.q||r.querySelector('.nm').textContent.includes(colState.q);
    r.style.display=(okF&&okQ)?'':'none';
  });
  /* 无命中的班级卡 / 年级卡整卡隐藏，全部无命中时显示空态；无筛选时全部恢复 */
  var anyG=false;
  document.querySelectorAll('#sc-apply .grade-card').forEach(function(g){
    var anyC=false;
    g.querySelectorAll('.grp-card').forEach(function(c){var vis=!active||[...c.querySelectorAll('.col-list .stu')].some(function(r){return r.style.display!=='none'});c.style.display=vis?'':'none';if(vis)anyC=true});
    g.style.display=anyC?'':'none';if(anyC)anyG=true;
  });
  apEmptySet(anyG?'':'nomatch');
  if(active){
    document.querySelectorAll('.grade-card.collapsed').forEach(function(g){
      g.classList.remove('collapsed');
      var gb=g.querySelector('.grade-body');
      if(gb)gb.style.maxHeight='2800px';
    });
    document.querySelectorAll('.grp-card.collapsed').forEach(function(c){
      c.classList.remove('collapsed');
      var pb=c.querySelector('.grp-body');
      if(pb)pb.style.maxHeight='1400px';
    });
  }
}
function colFilterSel(v){colState.f=v;colApply();colStatsHL()}
/* 统计栏四个数字可点击：点击即按该状态筛选并同步下拉；「在读学生」= 全部；当前筛选项标签变蓝加粗（与教师 / 学生管理统计栏同一交互） */
function colStatPick(v){ddSet('ap-filter',v);colFilterSel(v)}
function colStatsHL(){document.querySelectorAll('#ap-stats .it.tap').forEach(function(el){el.classList.toggle('on',el.getAttribute('data-f')===colState.f)})}
