/* -------- 信息确认页名单行状态切换（2026-10-26）：「确认无误」把该生行从待确认改为已确认、「取消确认」改回；班级 / 年级表头计数、统计栏「待确认 / 已确认」与首页宫格角标随之联动（同源同数） -------- */
/* 统计栏「待确认」按本人查看范围计全部；首页宫格角标只计「本人担任班主任、且本人持有覆盖该班『信息确认』权限」的班级（同班多名班主任均计，2026-10-26 定、2026-10-27 补权限条件，与请假「待我审批」同口径）：
   校长、年级组长等持有范围内信息确认权限但不是班主任的只是兜底处理，不是其待办；班主任的「信息确认」为平台锁定、学校不可取消（权限由 mePermOn 逐条任职关系取并集；王老师只有班主任 + 任课关系，2026-10-27 去掉原兼任的校级管理员）；行所属班级取自行的 onclick 参数 */
function apWaitSync(){
  var rows=[...document.querySelectorAll('.col-list .stu[data-cf="wait"]')],n=rows.length,el=document.getElementById('ap-st-wait');
  if(el)el.textContent=n;
  var me=typeof meRec==='function'&&meRec(),hr=me?dsCls(me).hr:[];
  hmSet('badge',rows.filter(function(r){var m=/go\('br','[^']*','([^']*)'/.exec(r.getAttribute('onclick')||'');return m&&hr.indexOf(m[1])>-1&&mePermOn('badge.confirm',m[1])}).length);
}
/* 「一键提醒未提交」按权限显隐（2026-10-27，PRD 2.1.1.13 权限表「一键提醒未提交」行）：本人持有覆盖名单内任一班级的「一键提醒未提交」时显示按钮；提醒人数只计持有该权限点的班级中的未提交。行所属班级取 onclick 参数，未提交行无 onclick 则由所在班级卡 id（grp-年级-班号）推出 */
function apRowCls(r){var m=/go\('br','[^']*','([^']*)'/.exec(r.getAttribute('onclick')||'');if(m)return m[1];var g=r.closest('.grp-card'),k=g&&/grp-(\d+)-(\d+)/.exec(g.id||'');return k?k[1]+'年级-'+k[2]+'班':''}
function apRemindCls(){var s={};[...document.querySelectorAll('.col-list .stu')].forEach(function(r){var c=apRowCls(r);if(c)s[c]=1});return Object.keys(s).filter(function(c){return mePermOn('badge.remind',c)})}
function apRemindSync(){var b=document.getElementById('ap-remind-btn');if(b)b.style.display=apRemindCls().length?'':'none'}
function apRemind(){var ok=apRemindCls(),n=[...document.querySelectorAll('.col-list .stu[data-cf="no"]')].filter(function(r){return ok.indexOf(apRowCls(r))>-1}).length;toast('已提醒 '+n+' 位未提交家长')}
function apNoRemindTog(){window.__apNoRemind=!window.__apNoRemind;apRemindSync();demoToast(window.__apNoRemind?'预览：学校已取消班主任「一键提醒未提交」且本人无其他职务覆盖——底部「一键提醒未提交」按钮隐藏，名单与统计栏不变（本次会话，再点恢复）':'已恢复：班主任持有「一键提醒未提交」，按钮显示，提醒人数按持有该权限点的班级计（王老师 3 人）')}
function apHdAdj(card,from,to){
  var el=card&&card.querySelector('.muted');if(!el)return;
  var m={},order=['未提交','待确认','已确认'];
  el.textContent.split('·').forEach(function(x){var t=x.trim().split(' ');if(t.length===2)m[t[0]]=+t[1]});
  m[from]=Math.max(0,(m[from]||0)-1);m[to]=(m[to]||0)+1;
  el.textContent=order.filter(function(k){return m[k]}).map(function(k){return k+' '+m[k]}).join(' · ');
}
/* 信息确认页各班学生顺序（2026-11-03）：待确认（老师自己的待办，点进去即可确认，首页宫格角标即计此项）→
   未提交（等家长提交，行不可点，由底部「一键提醒未提交」统一处理）→ 已确认；同状态内按姓名拼音（stuColl，见 1.4.3 人员名单排序）。
   只在每个班内部排，班级与年级顺序不变；在进入或返回本页时重排（办理记录页「确认无误 / 取消确认」后回来即见新位置），不在查看时当场挪动 */
const AP_CF_ORD={wait:0,no:1,ok:2};
function apSortRows(){
  document.querySelectorAll('#sc-apply .col-list').forEach(function(l){
    [...l.querySelectorAll(':scope>.stu')].sort(function(x,y){
      return AP_CF_ORD[x.dataset.cf]-AP_CF_ORD[y.dataset.cf]||stuColl.compare(x.querySelector('.nm').textContent.trim(),y.querySelector('.nm').textContent.trim());
    }).forEach(function(r){l.appendChild(r)});
  });
}
function cfSetRow(name,state){
  var row=[...document.querySelectorAll('.col-list .stu')].find(function(r){return r.querySelector('.nm').textContent.trim()===name});
  if(!row||row.dataset.cf===state)return;
  var from=row.dataset.cf,lab={wait:'待确认',ok:'已确认'};
  row.dataset.cf=state;
  var chip=row.querySelector('.chip');if(chip){chip.className='chip '+(state==='ok'?'teal':'amber');chip.firstChild.nodeValue=lab[state]}
  var sub=row.querySelector('.sub');
  if(sub){if(!row.dataset.sub0)row.dataset.sub0=sub.textContent;sub.textContent=state==='ok'?'确认时间 2026-07-06 09:41':row.dataset.sub0}
  apHdAdj(row.closest('.grp-card'),lab[from],lab[state]);apHdAdj(row.closest('.grade-card'),lab[from],lab[state]);
  var ok=document.getElementById('ap-st-ok');if(ok)ok.textContent=+ok.textContent+(state==='ok'?1:-1);
  apWaitSync();colApply();
}
function cfConfirm(){
  cfSetRow(brCurName,'ok');brCurStatus='ok';
  brBack();
  toast('已确认，信息无误');
}
function cfCancelConfirm(){
  var mask=document.createElement('div');
  mask.className='modal-mask';
  mask.innerHTML='<div class="modal-box"><div class="m-title">提示</div><div class="m-body">确定取消确认？</div><div class="m-btns"><button class="m-cancel">取消</button><button class="m-ok">确定</button></div></div>';
  document.body.appendChild(mask);
  void mask.offsetHeight;
  requestAnimationFrame(function(){mask.classList.add('show')});
  mask.querySelector('.m-cancel').onclick=function(){
    mask.classList.remove('show');
    setTimeout(function(){mask.remove()},220);
  };
  mask.querySelector('.m-ok').onclick=function(){
    mask.classList.remove('show');
    cfSetRow(brCurName,'wait');brCurStatus='wait';
    setTimeout(function(){mask.remove();brBack()},220);
  };
}
