/* ======== 对齐 tn 原型：办理记录 / 信息确认详情按学生参数进入（go 包装）与各模块初始渲染 ======== */
go=function(id,name,cls,status){
  if((id==='sc-cf-edit'||id==='sc-cf-view')&&name){
    cfEntryFrom=curScreen==='sc-msgs'?'sc-msgs':curScreen==='sc-wxpush'?'sc-home':'br';
    brCurName=name;brCurCls=cls||'';
    var cfRow=brRowOf(name);
    brCurStatus=(cfRow&&cfRow.dataset.cf)||status||'wait';
    if(id==='sc-cf-edit'&&(brCurStatus!=='wait'||!mePermOn('badge.confirm',brCurCls))){
      id='sc-cf-view';status=brCurStatus;
    }
  }
  if(id==='br'&&curScreen==='sc-msgs')brEntryFrom='sc-msgs';
  else if(id==='br'&&curScreen==='sc-apply')brEntryFrom='sc-apply';
  _go_orig(id);
  if(id==='sc-apply'){apSortRows();if(typeof apRemindSync==='function')apRemindSync()}
  if(!name)return;
  if(id==='sc-cf-edit'){
    var ch=(name||'').slice(-1);
    document.getElementById('cf-edit-avatar').textContent=ch;
    document.getElementById('cf-edit-avatar').className=cfAvClass(name,cls);
    document.getElementById('cf-edit-name').textContent=name;
    document.getElementById('cf-edit-cls').textContent=(cls||'')+' · 待确认';
    cfEditClsName=cls||'';cfEditCurG=cfEditClsName.split('-')[0];
    document.getElementById('cf-edit-cls-txt').textContent=cfEditClsName;
    var nmInput=document.querySelector('#sc-cf-edit input[type=text]');
    if(nmInput)nmInput.value=name;
  }
  if(id==='sc-cf-view'){
    var ch2=(name||'').slice(-1);
    document.getElementById('cf-view-avatar').textContent=ch2;
    document.getElementById('cf-view-avatar').className=cfAvClass(name,cls);
    document.getElementById('cf-view-name').textContent=name;
    document.getElementById('cf-view-cls').textContent=(cls||'')+(status==='wait'?' · 待确认':' · 已确认');
    /* 「取消确认」只给已确认且本人持有覆盖该班「信息确认」的记录；待确认记录因无权限进入只读页时不显示（2026-10-27） */
    var cfHint=document.getElementById('cf-view-hint');if(cfHint)cfHint.textContent=status==='wait'?'无确认权限，仅查看':'已确认，仅查看';/* 办理信息右侧提示随记录状态（2026-10-27） */
    var isHist=!!window.__brHist;window.__brHist=0;/* 历史办理记录只读，不提供「取消确认」 */
    var cfFoot=document.querySelector('#sc-cf-view .apply-foot');if(cfFoot)cfFoot.style.display=(status!=='wait'&&!isHist&&mePermOn('badge.confirm',cls||''))?'':'none';
    var nmInput2=document.querySelector('#sc-cf-view input[type=text]');
    if(nmInput2)nmInput2.value=name;
  }
  if(id==='br'){
    brRender(name,cls,status||'wait');
  }
};
